INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a8516f4c38afc5192d52db469147a14', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jm_algebra', 'algebra', 'inequalities am-gm cauchy-schwarz', '[]', '["quadratic equations","factoring","solving for x"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -2.0, '$$\text{If }x^2 - 4x + 3 = 0$$\text{, then find the value of }x$$\text{.}', '["1", "2", "3", "4"]', '3', 'Step 1: Factor the quadratic equation.,Step 2: Solve for x by setting each factor equal to 0.', '["Step 1: Factor the quadratic equation.", "Step 2: Solve for x by setting each factor equal to 0."]', '', 'mathematics.algebra.inequalities_am_gm_cauchy_schwarz', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:12:12.413Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a993a97b6f3f7bbcc47ca711fc3cd41', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation_geo_satellite', 'Gravitation', 'Geostationary satellite parking orbit', '[]', '["geostationary satellite","orbital period","Earth rotation","parking orbit","gravitation","circular orbit","satellite altitude"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'A geostationary satellite orbits Earth at an altitude where:', '["Its orbital period equals Earth''s rotational period", "It remains fixed over the equator at any height", "Its orbital speed is maximum for circular orbits", "It experiences no gravitational force"]', 'Its orbital period equals Earth''s rotational period', 'A geostationary satellite has an orbital period of 24 hours, matching Earth''s rotation. It orbits above the equator at ~35,786 km altitude. Gravitational force provides centripetal force. Lower orbits have higher speed, so geostationary is not the fastest.', '["Step 1: Define geostationary orbit: fixed relative to Earth''s surface", "Step 2: Requires orbital period = 24 hours", "Step 3: Must be equatorial and circular", "Step 4: Use $T = 2\\pi\\sqrt{\\frac{r^3}{GM}}$ to find altitude"]', 'T = 2\pi\sqrt{\frac{r^3}{GM}}', 'physics.gravitation.geostationary_orbit_misconception', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:11:46.203Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a9a336235f7f3b6f62de1027d33a4f7', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem', 'Biogeochemical cycles - nitrogen', '[]', '["nitrogen cycle","nitrogen fixation","ammonia","N₂ fixation","bacteria","ecosystem"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'In the nitrogen cycle, which process converts atmospheric nitrogen into ammonia?

$$\text{N}_2 \rightarrow \text{NH}_3$$', '["Nitrification", "Ammonification", "Denitrification", "Nitrogen fixation"]', 'Nitrogen fixation', 'Nitrogen fixation converts atmospheric N₂ into ammonia (NH₃) by bacteria.', '["Step 1: Identify conversion: N₂ → NH₃", "Step 2: Recall process: Nitrogen fixation"]', '', 'biology.ecosystem.nitrogen_cycle_confusion', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:10:56.270Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a9b0d6cba76fc55d624caf5bbbc65ac', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_1d', 'Motion in a Straight Line', 'Free fall and vertical motion', '[]', '["free fall","equations of motion","gravity","time of fall"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'A ball is dropped from 80 m. The time to reach ground is: (Take $g = 10\,m/s^2$)', '[]', '4', 'Use $s = \frac{1}{2}gt^2$. Solve $80 = \frac{1}{2} \times 10 \times t^2$ → $t = 4\,s$.', '["Step 1: $s = \\frac{1}{2}gt^2$", "Step 2: $80 = 5t^2$", "Step 3: $t^2 = 16 → t = 4$"]', 's = \frac{1}{2}gt^2', 'physics.kinematics.free_fall_sign_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:25:46.239Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a9c25e2b2c281ffd969fc6bc19bc713', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Number of elements in union n(AâˆªB)', '[]', '["sets","union of sets","cardinality","Venn diagram application","formula substitution"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Let $A$ and $B$ be two sets such that $n(A) = 25$, $n(B) = 32$, and $n(A \cap B) = 12$. What is $n(A \cup B)$?', '["45", "57", "37", "49"]', '45', 'Use the formula: $n(A \cup B) = n(A) + n(B) - n(A \cap B)$. Substituting values: $25 + 32 - 12 = 45$.', '["Step 1: Recall formula $n(A \\cup B) = n(A) + n(B) - n(A \\cap B)$", "Step 2: Substitute $n(A)=25$, $n(B)=32$, $n(A\\cap B)=12$", "Step 3: Compute $25 + 32 - 12 = 45$"]', 'n(A \cup B) = n(A) + n(B) - n(A \cap B)', 'math.sets.union_formula_sign_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:58:54.293Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7a9f9df337a0db69fdfecf14c0491c28', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_photochemistry', 'Advanced Physical Chemistry', 'Quantum yield and Stark-Einstein law of photochemistry', '[]', '["quantum yield","Stark-Einstein law","photochemistry","photon absorption","mole concept"]', 0, 0, '[]', 'Integer', NULL, 0, 2420, 'JEE_ADV_EASY', 2, -1.0, 'According to the Stark-Einstein law, each molecule absorbs one photon during a photochemical reaction. If $n$ photons are absorbed by $N$ molecules, what is the quantum yield $\phi$?', '[]', '1', 'Stark-Einstein law implies one photon per molecule; quantum yield is 1 for primary process.', '["Step 1: Apply Stark-Einstein law", "Step 2: $\\phi = \\text{molecules reacted} / \\text{photons absorbed} = 1$"]', '\phi = \frac{\text{molecules reacted}}{\text{photons absorbed}}', 'chemistry.photochemistry.stark_einstein_misconception', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:07:30.664Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aa01cd7d96ad63e21e89db8dc06f1a3', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_determinants', 'Determinants', 'Effect of elementary row operations', '[]', '["row operation","determinant sign change","elementary operations","matrix theory"]', 0, 0, '[]', 'MCQ', NULL, 0, 2125, 'JEE_MAINS_MEDIUM', 3, -1.0, 'If a determinant \(\Delta\) of a \(4\times4\) matrix is \(12\), what will be the value of the determinant after interchanging the first and third rows of the matrix?', '["12", "-12", "24", "0"]', '-12', 'Swapping two rows of a matrix changes the sign of its determinant while leaving its magnitude unchanged. Hence the new determinant is \(-\Delta = -12\).', '["Step 1: Identify the effect of a single row interchange on a determinant (sign reversal).", "Step 2: Apply the sign change to the original determinant value \\(12\\).", "Step 3: Record the new determinant as \\(-12\\)."]', 'determinant after row swap = - (original determinant)', 'math.algebra.determinant_row_swap', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:34:43.204Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aa89b5e21e05873440479baa1195be9', 'JEEMains', '11', 'Physics', 'phy_11_jm_rotational_motion', 'Rotational Motion', 'Rotational Dynamics', '[]', '["angular velocity","linear velocity"]', 0, 0, '[]', 'MCQ', NULL, 0, 1840, 'JEE_MAINS_EASY', 2, -1.0, 'A wheel of radius $R$ is rolling without slipping on a horizontal surface. If the angular velocity of the wheel is $omega$, what is the linear velocity of the center of the wheel?', '["$Romega$", "$2Romega$", "$\frac{Romega}{2}$", "$\frac{Romega}{4}$"]', '$Romega$', 'We can use the relationship between angular velocity and linear velocity to find the linear velocity.', '["Step 1: Write the relationship between angular velocity and linear velocity", "Step 2: Substitute the given values to find the linear velocity"]', 'v = Romega', 'physics.rotational_motion.angular_velocity', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:02.335Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aa974f876eff4c220bcee9569640d64', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics and Optical Instruments', 'Correction of Refractive Errors', '[]', '["myopia","far_point","lens_power","diverging_lens","spectacle_correction"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A myopic person has a far point at $0.25\,\text{m}$. What power of a spectacle lens is required to correct his vision for distant objects?', '["-4 D", "+4 D", "-2 D", "+2 D"]', '-4 D', 'For myopia the corrective lens is diverging, so its focal length is taken as the negative of the far‑point distance. Using $P=1/f$ (with $f$ in metres) gives $P=-1/0.25=-4\,\text{D}$. A common trap is to forget the negative sign for a diverging lens.', '["Step 1: For myopia, the far point distance $f$ is taken as the focal length of the required diverging lens.", "Step 2: Given far point $=0.25\\,\\text{m}$, so $f = -0.25\\,\\text{m}$ (negative sign for diverging lens).", "Step 3: Lens power $P = 1/f$ → $P = -1/0.25 = -4\\,\\text{D}$."]', 'P = -1/f', 'physics.optics.myopia_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:49:03.260Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aade83871cd0db97ebf88df3cba55c8', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Lamarckism vs. Darwinism', '[]', '["inheritance of acquired traits","natural selection","use and disuse","variation","evolutionary mechanisms"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which statement correctly distinguishes Lamarck''s theory of inheritance of acquired characteristics from Darwin''s theory of natural selection?', '["Lamarck proposed that traits acquired during an organism''s lifetime can be passed to offspring, whereas Darwin argued that only genetic mutations are inherited.", "Lamarck emphasized the role of use and disuse of organs, while Darwin emphasized differential survival and reproduction of variants already present in a population.", "Both Lamarck and Darwin agreed that environmental pressures directly shape the traits of offspring in each generation.", "Lamarck''s ideas were based on fossil evidence, whereas Darwin''s were derived solely from comparative anatomy."]', 'Lamarck emphasized the role of use and disuse of organs, while Darwin emphasized differential survival and reproduction of variants already present in a population.', 'Lamarck''s hypothesis states that organs used extensively become stronger and are inherited, whereas Darwin''s natural selection works on pre‑existing variation, favoring individuals better adapted to the environment.', '["Step 1: Recall Lamarck''s principle of use‑and‑disuse.", "Step 2: Recall Darwin''s principle of natural selection acting on existing variation.", "Step 3: Compare the two statements and select the one that matches the definitions."]', '', 'biology.evolution.lamarck_vs_darwin', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:22.934Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ab8ff81f35ed667dacc2d0f01aa4eea', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_inorganic', 'inorganic_chemistry', 'hsab_theory', '["chem_12_ja_acid_base"]', '["hsab","acid_base","soft_acid","hard_base","polarizability"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'According to HSAB (Hard‑Soft Acid‑Base) theory, which of the following statements are correct? (Select all that apply)', '["Soft acids prefer soft bases", "Hard acids have high polarizability", "Soft bases are larger and more polarizable", "Hard acids are typically transition metals in high oxidation states"]', '["SOFT ACIDS PREFER SOFT BASES", "SOFT BASES ARE LARGER AND MORE POLARIZABLE", "HARD ACIDS ARE TYPICALLY TRANSITION METALS IN HIGH OXIDATION STATES"]', 'HSAB theory states that soft acids match soft bases (A) and soft bases are indeed larger and more polarizable (C). Hard acids are small, highly charged, and often are transition metals in high oxidation states (D). Statement B is false because hard acids are low‑polarizable.', '["Step 1: Recall the definition of soft and hard species.", "Step 2: Match each statement with the definition.", "Step 3: Identify the false statement (high polarizability for hard acids)."]', '', 'chemistry.inorganic.hsab_misconception', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:16:18.439Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7abb4805abde58e7a784b2c70beb2c6a', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Power in resistive circuits', '[]', '["power","resistor","I^2R","electrical energy","Joule heating"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A resistor of resistance \(R = 10\,\Omega\) carries a current of \(I = 3\,\text{A}\). What is the power dissipated in the resistor?', '["90 W", "30 W", "0.33 W", "300 W"]', '90 W', 'Power in a resistive circuit is given by \(P = I^{2}R\). Substituting \(I = 3\,\text{A}\) and \(R = 10\,\Omega\) gives \(P = 3^{2}\times10 = 9\times10 = 90\,\text{W}\).', '["Step 1: Write the formula for power in a resistor: \\(P = I^{2}R\\).", "Step 2: Substitute the given values \\(I = 3\\,\\text{A}\\) and \\(R = 10\\,\\Omega\\).", "Step 3: Compute \\(3^{2}=9\\) and multiply by 10 to obtain \\(90\\,\\text{W}\\)."]', 'P = I^2 R', 'physics.current_electricity.power_resistive', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:37:18.646Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7abb9515f6fd9da934c7e4e735ac22b4', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vector_algebra', 'Vector Algebra', 'Section formula position vectors', '[]', '["position vector","section formula","midpoint","vector addition","component-wise operation","vector arithmetic","3D vectors","coordinate geometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'The position vectors of points A and B are $ \vec{a} = 2\hat{i} + 3\hat{j} - \hat{k} $ and $ \vec{b} = 4\hat{i} + \hat{j} + 3\hat{k} $. Find the position vector of the midpoint of AB.', '["$ 3\\hat{i} + 2\\hat{j} + \\hat{k} $", "$ 6\\hat{i} + 4\\hat{j} + 2\\hat{k} $", "$ 2\\hat{i} + \\hat{j} + 2\\hat{k} $", "$ \\hat{i} + \\hat{j} + \\hat{k} $"]', '$ 3\hat{i} + 2\hat{j} + \hat{k} $', 'Using section formula for midpoint: $ \vec{r} = \frac{\vec{a} + \vec{b}}{2} $. Adding vectors: $ (2+4)\hat{i} + (3+1)\hat{j} + (-1+3)\hat{k} = 6\hat{i} + 4\hat{j} + 2\hat{k} $, then divide by 2: $ 3\hat{i} + 2\hat{j} + \hat{k} $.', '["Step 1: Recall midpoint formula: $ \\vec{r} = \\frac{\\vec{a} + \\vec{b}}{2} $", "Step 2: Add corresponding components", "Step 3: Divide each component by 2"]', '\vec{r} = (\vec{a} + \vec{b})/2', 'math.vectors.section_formula_wrong_weighting', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:04.989Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7abbf46c1ec0d8ab201e7fba4d50e0a5', 'NEET', '12', 'Biology', 'bio_12_neet_genetics', 'Genetics', 'Transposons and mobile genetic elements', '[]', '["transposons","mobile genetic elements","Barbara McClintock","maize","gene regulation","jumping genes","genetic mutation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'Which of the following is TRUE about transposons, as discovered by Barbara McClintock in maize?', '["They are viral sequences integrated into the genome", "They are DNA segments that can move within the genome", "They are responsible for RNA splicing", "They are telomeric repeat sequences"]', 'They are DNA segments that can move within the genome', 'Barbara McClintock discovered transposable elements (transposons) in maize, which are DNA sequences capable of changing their position within the genome. This movement can alter gene expression and cause mutations. They are not viral in origin per se, not involved in splicing, and distinct from telomeres. Their mobility is key to their function in genetic regulation and evolution.', '["Step 1: Recall Barbara McClintock''s work on maize genetics.", "Step 2: She observed unstable color patterns in kernels.", "Step 3: Traced to mobile genetic elements changing position.", "Step 4: Named them controlling elements, now called transposons."]', '', 'biology.genetics.transposon_viral_origin_misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:09:23.175Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7abd26e3be75bac48b8384213d170eed', 'Board', '9', 'Science', 'chem_9_board_atoms', 'Atoms and Molecules', 'Dalton''s atomic theory postulates', '[]', '["Dalton''s theory","atomic theory","conservation of mass","chemical reactions","indivisible atoms","element identity"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1300, 'CLASS_9_BASIC', 4, 0.0, 'Which of the following is NOT a postulate of Dalton''s atomic theory?', '["Atoms are indivisible", "Atoms of the same element are identical", "Atoms can be created in chemical reactions", "Compounds are formed by combination of atoms"]', 'Atoms can be created in chemical reactions', 'Dalton''s theory states that atoms cannot be created, destroyed, or subdivided in chemical reactions. They are merely rearranged. The incorrect option violates the conservation of atoms in reactions.', '["Step 1: Recall Dalton''s postulates", "Step 2: Atoms are indivisible and indestructible", "Step 3: Atoms combine in fixed ratios to form compounds", "Step 4: Atoms are not created or destroyed in reactions"]', '', 'chemistry.atoms.dalton_creation_destruction', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1300 and target exam Board', '2026-05-20T12:00:58.442Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7abf1ac171c54d9ccaad51588e57147c', 'JEEMains', '11', 'Physics', 'phy_12_jm_waves', 'Waves and Sound', 'Speed of sound in gases', '["phy_12_jm_thermodynamics"]', '["speed of sound","temperature dependence","ideal gas","square root relationship"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The speed of sound in an ideal diatomic gas is given by $v = \sqrt{\frac{\gamma R T}{M}}$, where $\gamma = 1.4$. If the temperature of the gas is increased by $20\%$ while the gas composition remains unchanged, what is the approximate percentage increase in the speed of sound?', '["9.5\\% increase", "10\\% increase", "12\\% increase", "8\\% increase"]', '9.5\% increase', 'The speed of sound varies as $v \propto \sqrt{T}$. An increase of $20\%$ in temperature means $T'' = 1.20\,T$. Hence $v'' = v\sqrt{1.20} \approx v\times1.095$, i.e., about a $9.5\%$ increase.', '["Step 1: Identify the dependence $v \\propto \\sqrt{T}$ from the given formula.", "Step 2: Write the new temperature as $T'' = 1.20\\,T$.", "Step 3: Compute the ratio $v''/v = \\sqrt{1.20}$ and convert to percentage."]', 'v = \sqrt{\frac{\gamma R T}{M}}', 'physics.waves.speed_of_sound_temperature', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:02.089Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ac332f0b2b565ba914cf6c0fdf3ad4f', 'Board', '9', 'Mathematics', 'math_9_board_geometry', 'Geometry', 'Triangles congruence criteria SSS SAS AAS', '[]', '["congruence","triangles","SSS","geometry"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1050, 'CLASS_9_BASIC', 2, 0.0, 'Two triangles have sides 5 cm, 6 cm, 7 cm and 5 cm, 6 cm, 7 cm respectively. Which congruence criterion applies?', '["SSS", "SAS", "AAS", "RHS"]', 'SSS', 'All three sides equal → SSS congruence criterion.', '["Step 1: Compare all three sides", "Step 2: Equal → SSS"]', 'SSS congruence', 'math.geometry.congruence_criteria_confusion', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:08.903Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7acce7270e2e6e678928212e4e010809', 'Board', '9', 'Science', 'sci_9_board_motion_distance_displacement', 'Motion', 'Distance vs Displacement', '[]', '["scalar","vector","net displacement","direction","addition of vectors"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 4, 0.0, 'A particle moves 4 m east and then 3 m west along a straight line. What is the total displacement of the particle?', '["7 m east", "1 m east", "1 m west", "7 m west"]', '1 m east', 'Displacement = final position – initial position. Net movement = 4 m east − 3 m west = 1 m east.', '["Step 1: Assign east as positive direction.", "Step 2: Add the vectors: +4 m + (−3 m) = +1 m.", "Step 3: Interpret the sign: positive → east.", "Step 4: Choose the option representing 1 m east."]', '', 'physics.mechanics.displacement_sign_error', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:31:58.296Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ad0f2553d0e14d32a12f1bc67326f75', 'NEET', '11', 'Biology', 'bio_11_neet_respiration', 'Respiration in Plants', 'Respiratory quotient RQ calculation', '[]', '["respiratory quotient","RQ","glucose","fats","oxygen consumption","CO2 evolution","substrate oxidation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'When glucose is the respiratory substrate, the Respiratory Quotient (RQ) is 1.0. What will be the RQ when fats are used as the substrate?', '["Greater than 1", "Equal to 1", "Less than 1", "Zero"]', 'Less than 1', 'RQ = $\frac{CO_2 \text{ evolved}}{O_2 \text{ consumed}}$. Fats require more oxygen for oxidation compared to CO₂ produced. For example, tripalmitin has RQ ≈ 0.7. Hence, RQ < 1 for fats.', '["Step 1: Recall RQ = CO₂ evolved / O₂ consumed.", "Step 2: Understand fats are more reduced, requiring more O₂.", "Step 3: Less CO₂ is produced per O₂ consumed.", "Step 4: Conclude RQ < 1 for lipid substrates."]', 'RQ = \frac{CO_2 \text{ evolved}}{O_2 \text{ consumed}}', 'biology.respiration.rq_fat_greater_than_1', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:38.044Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ad6a23f09f55553199649c9f32a1eb7', 'Board', '10', 'Science', 'sci_10_board_magnetic_effects', 'Magnetic Effects', 'Magnetic field due to straight current-carrying wire', '[]', '["right-hand thumb rule","magnetic field direction","current carrying wire"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 2, 0.0, 'A straight current-carrying wire has current flowing upward. What is the direction of the magnetic field at a point east of the wire?', '["North", "South", "Into the plane", "Out of the plane"]', 'Into the plane', 'By right-hand thumb rule, upward current → field is into the plane east of wire.', '["Step 1: Apply right-hand rule", "Step 2: Thumb up (current), fingers curl into plane at east"]', '', 'science.magnetism.right_hand_rule_mistake', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:25.882Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ae223a619e864f056ac9d464396415a', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'General term', '[]', '["binomial coefficient","combination","expansion","term identification"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'What is the coefficient of $x^3y^2$ in the expansion of $(x+y)^5$?', '["10", "5", "20", "15"]', '10', 'The term containing $x^3y^2$ corresponds to $k=2$ in $C(5,k) x^{5-k} y^{k}$. $C(5,2)=\frac{5!}{2!3!}=10$.', '["Step 1: Write the general binomial term $C(n,k) x^{n-k} y^{k}$.", "Step 2: Set $k=2$ to obtain the $y^2$ factor, giving $x^{3}y^{2}$.", "Step 3: Compute $C(5,2)=10$."]', 'C(n,k)=\frac{n!}{k!(n-k)!}', 'math.binomial.coefficient_miscount', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:59:26.217Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ae3e4210803d96c0e7f5d6ab752b0a4', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'sin⁻¹(sin x) cos⁻¹(cos x) simplification', '[]', '["inverse trig","principal value","sin⁻¹(sin x)","range restriction","angle reduction"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, 0.0, 'The value of $ \sin^{-1}(\sin \frac{5\pi}{3}) $ is:', '[]', '-1.05', 'sin⁻¹(sin x) returns value in [-π/2, π/2]. 5π/3 ≡ -π/3 ⇒ answer = -π/3 ≈ -1.05.', '["Step 1: 5π/3 = 2π - π/3 → equivalent to -π/3", "Step 2: sin⁻¹(sin(5π/3)) = -π/3 ≈ -1.05"]', '\sin^{-1}(\sin x) = x \text{ only if } x \in [-\pi/2, \pi/2]', 'math.trig.inverse_range', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:10:39.257Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ae4c6a403bf662b4ca9a793652e345f', 'Board', '10', 'Mathematics', 'math_10_board_triangles', 'Triangles', 'Basic proportionality theorem', '[]', '["similar triangles","proportional segments","Thales theorem","parallel line"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'In triangle \(ABC\), points \(D\) and \(E\) lie on \(AB\) and \(AC\) respectively such that \(DE \parallel BC\). If \(\frac{AD}{AB}=\frac{1}{3}\), what is \(\frac{AE}{AC}\)?', '["1/3", "1/2", "2/3", "1"]', '1/3', 'By the basic proportionality theorem, when a line parallel to one side of a triangle cuts the other two sides, it divides those sides proportionally. Hence \(\frac{AD}{AB}=\frac{AE}{AC}=\frac{1}{3}\).', '["Step 1: Recognize the configuration as the basic proportionality (Thales) theorem.", "Step 2: Apply the theorem: \\(\\frac{AD}{AB}=\\frac{AE}{AC}\\).", "Step 3: Substitute the given ratio \\(\\frac{1}{3}\\) to obtain \\(\\frac{AE}{AC}=\\frac{1}{3}\\)."]', '', 'math.geometry.basic_proportionality', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:00.175Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aead5de186e237aa3a4603debb7a9b6', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_cauchy_schwarz', 'Mathematics', 'Inequalities', '[]', '["cauchy-schwarz","vector inequality","maximization","dot product"]', 0, 0, '[]', 'MCQ', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Let \(a,b,c\) be real numbers such that \(a^2+b^2+c^2 = 5\). Find the maximum possible value of the expression \(a+2b+3c\).', '["$\\sqrt{60}$", "$\\sqrt{65}$", "$\\sqrt{70}$", "$\\sqrt{75}$"]', '$\sqrt{70}$', 'Using Cauchy‑Schwarz, \((a+2b+3c)^2 \le (a^2+b^2+c^2)(1^2+2^2+3^2) = 5\times14 = 70\). Hence the maximum of \(a+2b+3c\) is \(\sqrt{70}\).', '["Step 1: Identify vectors \\(\\mathbf{u}=(a,b,c)\\) and \\(\\mathbf{v}=(1,2,3)\\).", "Step 2: Apply Cauchy‑Schwarz: \\((\\mathbf{u}\\cdot\\mathbf{v})^2 \\le (\\mathbf{u}\\cdot\\mathbf{u})(\\mathbf{v}\\cdot\\mathbf{v})\\).", "Step 3: Substitute the given sum of squares \\(a^2+b^2+c^2=5\\) and compute \\(\\mathbf{v}\\cdot\\mathbf{v}=1+4+9=14\\).", "Step 4: Take the square root to obtain the maximum value \\(\\sqrt{70}\\)."]', '(\sum a_i^2)(\sum b_i^2) \ge (\sum a_i b_i)^2', 'math.inequalities.cauchy_schwarz_application', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:34:49.721Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aec4d5dbe849720636af60d1df5acc8', 'NEET', '12', 'Biology', 'bio_12_hr_fertilisation_implantation', 'fertilisation_implantation', 'fertilisation_implantation', '[]', '["acrosome_reaction","sperm","fertilisation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$$\text{During fertilisation, which of the following is NOT a characteristic of the acrosome reaction in the sperm?}$$', '["Release of enzymes to break down the zona pellucida", "Release of calcium ions to activate the acrosome reaction", "Release of histones to compact the DNA", "Release of proteases to degrade the sperm plasma membrane"]', 'Release of histones to compact the DNA', 'Step 1: Recall the characteristics of the acrosome reaction in the sperm.
Step 2: Identify the option that is NOT a characteristic of the acrosome reaction.
Step 3: Eliminate the incorrect options based on the characteristics of the acrosome reaction.', '["Step 1: Recall the characteristics of the acrosome reaction in the sperm.", "Step 2: Identify the option that is NOT a characteristic of the acrosome reaction.", "Step 3: Eliminate the incorrect options based on the characteristics of the acrosome reaction."]', '', 'biology.emi.fertilisation_implantation', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:21:48.959Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7af14d1334d6ce279d1651ed7c1923b8', 'Board', '9', 'Mathematics', 'math_9_geometry_parallel', 'Geometry', 'Parallel lines and transversal', '[]', '["parallel lines","transversal","interior angles","supplementary angles","angle relationships"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'CLASS_9_BASIC', 3, 0.0, 'Two parallel lines $l_1$ and $l_2$ are cut by a transversal $t$. If the interior angle on the same side of the transversal at the intersection with $l_1$ measures $110^\circ$, what is the measure of the interior angle on the same side at the intersection with $l_2$?', '["$70^\\circ$", "$110^\\circ$", "$90^\\circ$", "$130^\\circ$"]', '$70^\circ$', 'Interior angles on the same side of a transversal intersecting parallel lines are supplementary; they add up to $180^\circ$. Hence the required angle is $180^\circ - 110^\circ = 70^\circ$.', '["Step 1: Identify the pair of interior angles on the same side of the transversal.", "Step 2: Apply the supplementary property (sum = $180^\\circ$).", "Step 3: Subtract the given angle from $180^\\circ$ to find the unknown angle."]', 'Interior angles on same side = $180^\circ$', 'math.geometry.parallel.interior_same_side', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1200 and target exam Board', '2026-05-20T12:52:05.445Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7af3ef4bfedd99904cfbe94aea741a41', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'Binomial coefficients properties', '[]', '["binomial coefficients","sum of coefficients","$2^n$","expansion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'The sum of the binomial coefficients in the expansion of $(1 + x)^{10}$ is equal to:', '["1024", "512", "2048", "256"]', '1024', 'Sum of coefficients = $2^n$. For $n=10$, $2^{10} = 1024$.', '["Set $x=1$ in $(1+x)^n$", "Get $2^n = 2^{10} = 1024$"]', '\sum \binom{n}{r} = 2^n', 'math.binomial.coefficient_sum_base_case', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:11:29.684Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7af8e10a2b8777fc065d016f9daef593', 'JEEMains', '12', 'Mathematics', 'math_12_jm_differential_equations', 'mathematics.differential_equations.applications', 'Applications — population growth cooling', '[]', '["Differential Equations","Population Growth","Cooling"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, 0.0, '$$\int \frac{1}{x^2 + 1} dx = \tan^{-1} x + C$$
Find the value of $$\int \frac{1}{x^2 + 1} dx$$ when $$x = 1$$.', '[]', '0.785', 'Step 1: Use the given integral formula to find the value of the integral.\nStep 2: Substitute $x = 1$ into the equation to find the value of the integral.\nStep 3: Simplify the expression to find the final answer.', '["Step 1: Use the given integral formula to find the value of the integral.", "Step 2: Substitute $x = 1$ into the equation to find the value of the integral.", "Step 3: Simplify the expression to find the final answer."]', '\int \frac{1}{x^2 + 1} dx = \tan^{-1} x + C', 'mathematics.differential_equations.traps_on_application', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:23.486Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7afb9cc76ef8031d295c2734e5f75b5d', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermo', 'Thermodynamics', 'Specific heat ratio $\gamma$', '[]', '["specific_heat","ideal_gas","gamma_ratio","degrees_of_freedom"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'For an ideal gas, the ratio of specific heats $\gamma = \frac{C_p}{C_v}$ depends on the degrees of freedom. What is the approximate value of $\gamma$ for a diatomic gas at room temperature?', '["1.4", "1.67", "1.2", "1.0"]', '1.4', 'A diatomic gas has 5 active degrees of freedom (3 translational + 2 rotational). Hence $\gamma = \frac{f+2}{f}=\frac{5+2}{5}=\frac{7}{5}=1.4$.', '["Step 1: Identify the number of active degrees of freedom $f$ for a diatomic gas (5).", "Step 2: Use the formula $\\gamma = (f+2)/f$.", "Step 3: Substitute $f=5$ to obtain $\\gamma = 7/5 = 1.4$."]', '$\gamma = \frac{C_p}{C_v}=\frac{f+2}{f}$', 'physics.thermo.gamma_ratio', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:57:34.925Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7afdefdb4284560fbdc987371d91bc15', 'Board', '10', 'Mathematics', 'math_10_polynomials_remainder', 'Polynomials', 'Remainder Theorem', '[]', '["remainder theorem","polynomial division","evaluation","synthetic division"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 3, 0.0, 'Find the remainder when the polynomial $P(x)=2x^{3}-3x^{2}+x-5$ is divided by $(x-2)$. Choose the correct remainder.', '["-3", "1", "5", "7"]', '1', 'By the Remainder Theorem, the remainder equals $P(2)$. Substituting $x=2$ gives $2(8)-3(4)+2-5 = 1$, so the remainder is 1.', '["Step 1: Apply the Remainder Theorem: remainder = $P(c)$ for divisor $(x-c)$.", "Step 2: Evaluate $P(2) = 2(2)^{3} - 3(2)^{2} + 2 - 5$.", "Step 3: Compute $2\\times8 - 3\\times4 + 2 - 5 = 1$."]', 'Remainder theorem: remainder = $P(c)$ when divided by $(x-c)$', 'math.algebra.remainder_theorem_evaluation', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:42.124Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aff49d2ffd286dd66e7359df0abce10', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'Permutations and Combinations', 'Rank of word in dictionary', '[]', '["rank of word","permutations","lexicographic order"]', 0, 0, '[]', 'Integer', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, 0.0, 'Find the rank of the word ''MATH'' in dictionary order among all permutations of its letters.', '[]', '15', 'Fix letters stepwise: A,H,M,T. Words starting with A,H → 6+6=12. M→A,T,H: ''MA''→T,H → ''MATH'' is 3rd → 12+3=15.', '["Step 1: Alphabetical order: A,H,M,T", "Step 2: Words starting with A or H: 3! each = 6+6=12", "Step 3: MA→T,H: ''MATH'' is 3rd → 12+3=15"]', 'Rank = sum of permutations before each position', 'math.pnc.rank_lexicographic_order', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:45.277Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7aff99d921409b509289dd389b2af117', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_phase_diagrams', 'Phase Diagrams', 'Lever rule in eutectic systems', '[]', '["eutectic","lever rule","binary alloy","fraction of liquid","mole fraction","phase equilibrium"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 4, -2.0, 'In a binary eutectic alloy of components A and B, the eutectic composition is 30 mol% A and 70 mol% B. At the eutectic temperature the solid phases have compositions 80 mol% A (α) and 20 mol% A (β). A sample of the alloy contains 40 mol% A. Using the lever rule, what is the fraction of liquid phase present at the eutectic temperature?', '["0.25", "0.33", "0.40", "0.50"]', '0.33', 'The lever rule for a eutectic gives $f_L = \frac{C_0 - C_\beta}{C_\alpha - C_\beta}$, where $C_0$ is the overall composition, $C_\alpha$ and $C_\beta$ are the compositions of the two solid phases. Substituting $C_0=0.40$, $C_\alpha=0.80$, $C_\beta=0.20$ yields $f_L = (0.40-0.20)/(0.80-0.20)=0.20/0.60=0.33$.', '["Step 1: Identify the overall mole fraction of A, $C_0 = 0.40$.", "Step 2: Write the compositions of the solid phases: $C_\\alpha = 0.80$, $C_\\beta = 0.20$.", "Step 3: Apply the lever rule formula $f_L = (C_0 - C_\\beta)/(C_\\alpha - C_\\beta)$.", "Step 4: Compute $f_L = (0.40-0.20)/(0.80-0.20) = 0.20/0.60 = 0.33$."]', 'f_L = \frac{C_0 - C_\beta}{C_\alpha - C_\beta}', 'chemistry.phase_diagrams.lever_rule_mistake', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:11.360Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b009a3435d94b5512fb844584fbb01e', 'NEET', '12', 'Biology', 'bio_12_neet_genetics', 'Molecular Basis of Inheritance', 'Genetic code - degeneracy', '[]', '["genetic code","degeneracy","codon","amino acid","molecular biology"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'Which property of the genetic code explains that a single amino acid can be coded by more than one codon?', '["Unambiguous", "Universal", "Degenerate", "Non-overlapping"]', 'Degenerate', 'Degeneracy means multiple codons code for same amino acid.', '["Step 1: Recall genetic code properties", "Step 2: Match ''multiple codons → same amino acid'' = degeneracy"]', '', 'bio.genetics.code_property_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:05:17.908Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b02a7005ff939b9a016b483dc1919c8', 'JEEMains', '12', 'Chemistry', 'che_12_jm_alcohols', 'Alcohols, Phenols and Ethers', 'Preparation of Alcohols – Hydration of Alkenes', '[]', '["acid‑catalyzed hydration","stoichiometry","theoretical yield","molar mass calculation","alkene to alcohol conversion"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, 0.0, 'When 0.050 mol of ethene (\(\mathrm{C_2H_4}\)) is completely hydrated in the presence of excess \(\mathrm{H_2SO_4}\) catalyst, the theoretical yield of ethanol (\(\mathrm{C_2H_5OH}\)) is obtained. Calculate the mass of ethanol (in grams) that can be formed. (Molar mass of ethanol = 46 g·mol⁻¹).', '[]', '2.3', 'The hydration reaction is 1:1 (\(\mathrm{C_2H_4 + H_2O \rightarrow C_2H_5OH}\)). Thus, 0.050 mol of ethene gives 0.050 mol of ethanol. Mass = moles × molar mass = 0.050 × 46 = 2.30 g.', '["Step 1: Write the balanced hydration equation: \\(\\mathrm{C_2H_4 + H_2O \\rightarrow C_2H_5OH}\\).", "Step 2: Note the 1:1 stoichiometric ratio between ethene and ethanol.", "Step 3: Multiply the moles of ethanol (0.050 mol) by its molar mass (46 g·mol⁻¹) to obtain the mass.", "Step 4: Compute 0.050 × 46 = 2.30 g."]', 'mass = n \times M', 'chemistry.alcohols.hydration_yield', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:44.559Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b059d14fcab94b0f040f4416cb1c291', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Trigonometric Functions', 'Inverse Trigonometric Functions – Principal Value', '[]', '["inverse_trig","principal_value","arcsin","domain_range","angle_measure"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Evaluate the principal value of $\displaystyle \sin^{-1}\!\left(\frac{1}{2}\right)$. Choose the correct value from the options below.', '["$-\\frac{\\pi}{6}$", "$\\frac{\\pi}{6}$", "$\\frac{5\\pi}{6}$", "$-\\frac{5\\pi}{6}$"]', '$\frac{\pi}{6}$', 'The principal value of $\sin^{-1}x$ lies in $[-\pi/2,\pi/2]$. Since $\sin(\pi/6)=1/2$, the principal value is $\pi/6$.', '["Step 1: Recall the range of $\\sin^{-1}x$ is $[-\\pi/2,\\pi/2]$.", "Step 2: Identify the angle whose sine is $1/2$ within this range.", "Step 3: $\\sin(\\pi/6)=1/2$, so the principal value is $\\pi/6$."]', '$\sin^{-1}x \in[-\pi/2,\pi/2]$', 'math.trig.principal_value_selection', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:57:38.551Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b05fbcb548a87d05a5d478cdbc3e627', 'JEEAdvanced', '12', 'Physics', 'phy_12_jm_advanced_waves', 'Advanced Wave Physics', 'Wave packets — phase velocity vs group velocity vg=dω/dk', '[]', '["Wave Packet","Phase Velocity","Group Velocity"]', 0, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'A wave packet is a localized wave function that can be described by a wave function of the form $\psi(x) = e^{ikx}$. What is the phase velocity of the wave packet if the group velocity is $v_g = \frac{d\omega}{dk} = 2$?', '[]', '2', 'Step 1: Recall the relationship between phase velocity and group velocity, $v_p = \frac{\omega}{k}$. Step 2: Plug in the given value, $v_g = \frac{d\omega}{dk} = 2$. Step 3: Determine the phase velocity of the wave packet.', '["Step 1: Recall the relationship between phase velocity and group velocity, $v_p = \\frac{\\omega}{k}$.", "Step 2: Plug in the given value, $v_g = \\frac{d\\omega}{dk} = 2$.", "Step 3: Determine the phase velocity of the wave packet."]', '', 'physics.advanced_waves.wave_packet_phase_velocity', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:53:56.825Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b07ee8684a9c878789e2fed9ccfd8c8', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Simple pendulum period conditions', '["phy_11_jm_fluid_mechanics"]', '["simple pendulum","time period","buoyant force","SHM","effective gravity"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, -1.0, 'A simple pendulum has time period $T$ in air. If it is completely immersed in water (non-viscous), its new period becomes:', '["$T$", "$>T$", "$<T$", "$2T$"]', '$T$', 'Buoyancy doesn''t affect time period of simple pendulum as restoring force and mass reduce proportionally.', '["Apply formula $T = 2\\pi\\sqrt{l/g}$", "Note effective g unchanged in non-viscous fluid"]', 'T = 2\pi\sqrt{l/g}', 'physics.oscillations.buoyancy_effect', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:12:13.178Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b0a1f8294f3429cf11a4db248753eb6', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Fertilisation implantation', '[]', '["Fertilization","Human Reproduction","Sperm","Egg"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Fertilization in humans occurs when $', '["A sperm fuses with an egg.", "An egg fuses with another egg.", "A sperm fuses with another sperm.", "An egg fuses with a somatic cell."]', 'A sperm fuses with an egg.', 'Fertilization in humans occurs when a sperm fuses with an egg.', '["Step 1: A sperm penetrates the outer layer of the egg.", "Step 2: The sperm fuses with the egg."]', '', 'biology.human_reproduction.fertilization', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:38:14.298Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b0aaecf072ddcef71e38c4f57c52190', 'JEEMains', '11', 'Physics', 'phy_12_jm_waves', 'Waves', 'Normal modes and harmonics', '[]', '["standing wave","fixed ends","harmonic","wavelength"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A string of length $L$ is fixed at both ends and vibrates in its third harmonic. What is the wavelength $\lambda$ of the standing wave?', '["$\\frac{2L}{3}$", "$\\frac{L}{3}$", "$L$", "$2L$"]', '$\frac{2L}{3}$', 'For a string fixed at both ends, allowed wavelengths are $\lambda_n = \frac{2L}{n}$. With $n=3$, $\lambda = \frac{2L}{3}$.', '["Step 1: Identify the mode number $n=3$.", "Step 2: Use the formula $\\lambda = \\frac{2L}{n}$ for fixed ends.", "Step 3: Substitute $n=3$ to obtain $\\lambda = \\frac{2L}{3}$."]', '$\lambda = \frac{2L}{n}$', 'physics.waves.normal_modes_wavelength', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:31:26.548Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b0fe14b3240545478a27172234e79f7', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Gravitational field of a spherical shell', '[]', '["gravitational field","spherical shell","shell theorem","Newton''s law of gravitation","field inside shell"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A thin spherical shell of mass \(M\) and radius \(R\) produces a gravitational field. What is the magnitude and direction of the gravitational field at a point located at a distance \(r\) from the centre of the shell, where \(r < R\) (i.e., inside the shell)?', '["Zero", "GM/R^{2} directed outward", "GM/R^{2} directed inward", "GM/r^{2} directed inward"]', 'Zero', 'By the shell theorem, a uniform spherical shell exerts no net gravitational force on a particle located anywhere inside it. Hence the gravitational field inside the shell is zero.', '["Step 1: Recall the shell theorem for gravitation.", "Step 2: State that the net field inside a uniform spherical shell is zero.", "Step 3: Conclude that the magnitude is zero and direction is irrelevant."]', '', 'physics.gravitation.field_inside_shell', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:44.433Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b106cc9d8ee0bc6196e23e26d21d138', 'JEEMains', '12', 'Chemistry', 'che_12_jm_freon_ozone', 'Haloalkanes and Haloarenes', 'Freons (CFCs) and ozone depletion', '[]', '["CFC","ozone depletion","photolysis","stratosphere","atmospheric lifetime"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements about the chlorofluorocarbon CFC‑12 (CCl₂F₂) is correct regarding its role in stratospheric ozone depletion?', '["Each molecule of CFC‑12 releases two chlorine atoms upon photolysis in the stratosphere.", "CFC‑12 is chemically stable in the troposphere but undergoes photolytic cleavage in the stratosphere, releasing chlorine atoms that catalytically destroy ozone.", "CFC‑12 has an atmospheric lifetime of less than one year, so it does not reach the stratosphere in significant amounts.", "CFC‑12 does not contain any fluorine atoms, only chlorine and carbon."]', 'CFC‑12 is chemically stable in the troposphere but undergoes photolytic cleavage in the stratosphere, releasing chlorine atoms that catalytically destroy ozone.', 'CFC‑12 is inert in the lower atmosphere, allowing it to accumulate. In the stratosphere UV radiation breaks the C–Cl bond, liberating Cl atoms that participate in catalytic cycles that destroy ozone molecules.', '["Step 1: Recognise that CFC‑12 contains both chlorine and fluorine atoms (CCl₂F₂).", "Step 2: Recall that CFCs are chemically stable in the troposphere but are photolyzed in the stratosphere.", "Step 3: Identify the correct statement that links photolysis to catalytic ozone destruction."]', '', 'chemistry.haloalkanes.cfc_ozone_role', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:55:32.107Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b12bba05e2daa7435854f6be85803b2', 'JEEMains', '12', 'Mathematics', 'math_12_jm_product_rule', 'Continuity and Differentiability', 'Product rule', '[]', '["product rule","differentiation","trigonometric functions","evaluation at a point"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'Find the derivative of \(f(x)=x^{3}\sin x\) at \(x=\dfrac{\pi}{2}\). Give your answer correct to two decimal places.', '[]', '7.4', 'Using the product rule, \(f''(x)=3x^{2}\sin x + x^{3}\cos x\). At \(x=\pi/2\), \(\sin(\pi/2)=1\) and \(\cos(\pi/2)=0\), so \(f''(\pi/2)=3(\pi/2)^{2}=3\pi^{2}/4\approx7.40\).', '["Step 1: Apply the product rule: \\(f''(x)=3x^{2}\\sin x + x^{3}\\cos x\\).", "Step 2: Substitute \\(x=\\pi/2\\) and evaluate trigonometric functions.", "Step 3: Simplify to \\(3(\\pi/2)^{2}\\).", "Step 4: Compute the numerical value and round to two decimal places."]', 'If \(u\) and \(v\) are functions, \((uv)'' = u''v + uv''\)', 'math.calculus.product_rule_evaluation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:13.833Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b219ce688e4bd4b8a31c9aa553ad570', 'Board', '10', 'Mathematics', 'math_10_probability', 'Mathematics', 'Coin toss probability', '[]', '["probability","coin toss","combinatorics","sample space"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'A fair coin is tossed three times. What is the probability of getting exactly two heads?', '["1/8", "3/8", "1/2", "3/4"]', '3/8', 'Total possible outcomes = $2^3 = 8$. The favorable outcomes with exactly two heads are HHT, HTH, THH – three in number. Hence probability = $3/8$.', '["Step 1: Determine total number of outcomes: $2^3 = 8$.", "Step 2: List outcomes with exactly two heads: HHT, HTH, THH (3 outcomes).", "Step 3: Compute probability = favorable/total = $3/8$."]', 'Probability = \frac{\text{favorable outcomes}}{\text{total outcomes}}', 'math.probability.coin_toss', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:01.198Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b23714174dfad8281cb9f502a0be8e3', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Velocity and acceleration in SHM', '[]', '["SHM speed","displacement in SHM","angular frequency","maximum speed","kinematics of SHM","energy in SHM","velocity-amplitude relation","oscillatory motion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 5, -1.0, 'A particle executes simple harmonic motion with angular frequency $\omega$ and amplitude $A$. If its displacement is $\frac{A}{2}$, the ratio of its speed to its maximum speed is:

$$
\text{A. } \frac{1}{2}
$$

$$
\text{B. } \frac{\sqrt{3}}{2}
$$

$$
\text{C. } \frac{\sqrt{2}}{2}
$$

$$
\text{D. } \frac{\sqrt{3}}{4}
$$', '["\\frac{1}{2}", "\\frac{\\sqrt{3}}{2}", "\\frac{\\sqrt{2}}{2}", "\\frac{\\sqrt{3}}{4}"]', '\frac{\sqrt{3}}{2}', 'Speed in SHM is given by $v = \omega \sqrt{A^2 - x^2}$. At $x = \frac{A}{2}$, $v = \omega \sqrt{A^2 - \left(\frac{A}{2}\right)^2} = \omega A \sqrt{1 - \frac{1}{4}} = \omega A \frac{\sqrt{3}}{2}$. Maximum speed $v_{\text{max}} = \omega A$. So ratio $\frac{v}{v_{\text{max}}} = \frac{\sqrt{3}}{2}$.', '["Write speed formula: v = ω√(A² - x²)", "Substitute x = A/2", "Simplify: √(A² - A²/4) = A√(3/4) = A√3/2", "So v = ωA√3/2", "v_max = ωA → ratio = √3/2"]', 'v = \omega \sqrt{A^2 - x^2}', 'physics.shm.speed_formula_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:22.036Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b2545699f8736eb002a894ff6893f0f', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Standard limits sin(x)/x as x→0', '[]', '["Limits","Derivatives","Standard Limits"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'Find the limit of the expression $\frac{\text{sin}(x)}{x}$ as $x$ approaches $0$.', '["$0$", "$1$", "$\frac{1}{2}$", "$\frac{2}{3}$"]', '$1$', 'Step 1: Recall the definition of the limit of a function $f(x)$ as $x$ approaches $a$.,Step 2: Plug in the values of $f(x) = \frac{\text{sin}(x)}{x}$ and $a = 0$ into the definition to get the limit.', '["Step 1: Recall the definition of the limit of a function $f(x)$ as $x$ approaches $a$.", "Step 2: Plug in the values of $f(x) = \frac{\text{sin}(x)}{x}$ and $a = 0$ into the definition to get the limit."]', '$rac{	ext{sin}(x)}{x}$', 'math.limits_derivatives.standard_limits', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:00.167Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b2c0d5d89ad2fac68032f94c5235b55', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_kinetics', 'Chemical Kinetics', 'Arrhenius equation activation energy', '[]', '["Arrhenius equation","activation energy","rate constant","temperature dependence","logarithmic manipulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2300, 'JEE_MAINS_HARD', 4, -1.0, 'The rate constant of a reaction is $k_1 = 0.025\,\text{s}^{-1}$ at $300\,\text{K}$ and $k_2 = 0.10\,\text{s}^{-1}$ at $350\,\text{K}$. Using the Arrhenius equation, calculate the activation energy $E_a$ (in kJ·mol$^{-1}$).', '["24 kJ·mol$^{-1}$", "30 kJ·mol$^{-1}$", "15 kJ·mol$^{-1}$", "45 kJ·mol$^{-1}$"]', '24 kJ·mol$^{-1}$', 'From $\ln(k_2/k_1)= -E_a/R\,(1/T_2-1/T_1)$, we get $\ln 4 = 1.3863$ and $1/T_2-1/T_1 = -4.76\times10^{-4}\,\text{K}^{-1}$. Solving gives $E_a \approx 2.42\times10^{4}\,\text{J mol}^{-1}=24\,\text{kJ mol}^{-1}$.', '["Step 1: Write the Arrhenius form $\\ln(k_2/k_1)= -E_a/R\\,(1/T_2-1/T_1)$.", "Step 2: Compute $\\ln(k_2/k_1)=\\ln(0.10/0.025)=\\ln 4=1.3863$.", "Step 3: Evaluate $1/T_2-1/T_1 = 1/350 - 1/300 = -4.7619\\times10^{-4}\\,\\text{K}^{-1}$.", "Step 4: Solve for $E_a = 1.3863 \\times R / 4.7619\\times10^{-4} \\approx 2.42\\times10^{4}\\,\\text{J mol}^{-1}=24\\,\\text{kJ mol}^{-1}$."]', '$\ln\frac{k_2}{k_1}= -\frac{E_a}{R}\left(\frac{1}{T_2}-\frac{1}{T_1}\right)$', 'chemistry.kinetics.arrhenius_activation_energy', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:11.786Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b303e28fa4df06f77cb055a173cb394', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols_phenols_ethers', 'Alcohols Phenols and Ethers', 'Preparation of alcohols — hydration reduction', '[]', '["hydration of alkenes","Markovnikov''s rule","propan-2-ol","acid catalysis"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, -1.0, 'The major product of acid-catalyzed hydration of propene is', '["Propan-1-ol", "Propan-2-ol", "Propane", "Propyne"]', 'Propan-2-ol', 'Hydration follows Markovnikov''s rule; OH adds to more substituted carbon.', '["Step 1: Identify hydration mechanism", "Step 2: Apply Markovnikov''s rule", "Step 3: OH on C2 gives propan-2-ol"]', '', 'chem.alcohol.hydration_regiochemistry', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:08.942Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b33487a4d06943f74092778cbdbfedd', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals_application', 'Application of Integrals', 'Area between two curves', '["math_12_jm_calculus"]', '["area between curves","definite integral","intersection points","function comparison","integration of power functions"]', 1, 0, '[]', 'Integer', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 6, 0.0, 'The area enclosed between the curves $y = x^2$ and $y = \sqrt{x}$ from $x = 0$ to $x = 1$ is:', '[]', '0.33', 'The curves intersect at $x = 0$ and $x = 1$. In $[0,1]$, $\sqrt{x} \geq x^2$, so area $A = \int_0^1 (\sqrt{x} - x^2)\,dx = \int_0^1 \left(x^{1/2} - x^2\right)dx = \left[\frac{2}{3}x^{3/2} - \frac{1}{3}x^3\right]_0^1 = \frac{2}{3} - \frac{1}{3} = \frac{1}{3} \approx 0.33$.', '["Find points of intersection: $x^2 = \\sqrt{x} \\Rightarrow x = 0,1$", "Determine upper function: $\\sqrt{x} \\geq x^2$ in $[0,1]$", "Set up integral: $\\int_0^1 (\\sqrt{x} - x^2) dx$", "Integrate: $\\frac{2}{3}x^{3/2} - \\frac{1}{3}x^3$", "Evaluate from 0 to 1: $\\frac{2}{3} - \\frac{1}{3} = \\frac{1}{3}$", "Round to two decimals: 0.33"]', 'A = \int_a^b |f(x) - g(x)|\,dx', 'math.integral.limits_or_order', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:50.064Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b346a2937c6f40acdf25a9d12510692', 'NEET', '11', 'Biology', 'bio_11_neet_biomolecules', 'Biomolecules', 'Vitamins coenzymes and deficiency diseases', '[]', '["vitamin_b12","pernicious_anemia","deficiency_diseases"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'NEET_MEDIUM', 2, -1.0, 'Deficiency of which vitamin causes Pernicious Anemia?', '["Vitamin B12", "Vitamin B6", "Vitamin C", "Vitamin K"]', 'Vitamin B12', 'B12 deficiency impairs RBC formation causing Pernicious Anemia.', '["Step 1: Identify disease: Pernicious Anemia", "Step 2: Recall associated vitamin: Cobalamin (B12)"]', '', 'bio.vitamins.deficiency_match', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:46:02.285Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b358b5e9ccdca81222e34b272227d19', 'Board', '9', 'Science', 'sci_9_board_motion', 'Motion', 'Relative motion basics', '[]', '["relative motion","speed","same direction","motion in straight line","velocity difference","class 9 science","kinematics basics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1000, 'CLASS_9_BASIC', 3, 0.0, 'Two cars A and B are moving in the same direction with speeds 60 km/h and 40 km/h respectively. What is the relative speed of car A with respect to car B?', '["20 km/h", "100 km/h", "-20 km/h", "0 km/h"]', '20 km/h', 'When two objects move in the same direction, their relative speed is the difference of their speeds. So, relative speed of A w.r.t. B is $60 - 40 = 20$ km/h. The positive value indicates A is moving faster than B.', '["Step 1: Identify direction: same direction", "Step 2: Use relative speed formula: $v_{AB} = v_A - v_B$", "Step 3: Compute: $60 - 40 = 20$ km/h"]', 'v_{AB} = v_A - v_B', 'science.motion.relative_speed_direction_error', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:59:31.882Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b36e3e4cf7c9866034befb8921df6b8', 'Board', '10', 'Science', 'bio_10_board_life_processes', 'Life Processes', 'Excretion nephron kidney urine', '[]', '["nephron","urine formation","kidney","excretion"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 2, 0.0, 'Where is urine formed in the human body?', '["Nephron", "Ureter", "Bladder", "Urethra"]', 'Nephron', 'Nephron is the functional unit of the kidney where urine is formed.', '["Step 1: Recall structure of excretory system", "Step 2: Identify nephron as site of urine formation"]', '', 'biology.excretion.organ_vs_functional_unit', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_life_proc', '2026-05-22T15:19:35.277Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b371deb268d7eb8e20dae8ca71c916a', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Indeterminate forms L''Hopital basics', '["math_11_jm_trigonometric_limits"]', '["L''Hopital''s Rule","indeterminate form","trigonometric limit","derivative","limit evaluation"]', 1, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 5, -1.0, 'Evaluate: $$\lim_{x \to 0} \frac{\sin(3x)}{\tan(5x)}$$', '["$\\frac{3}{5}$", "$\\frac{5}{3}$", "1", "0"]', '$\frac{3}{5}$', 'As $x \to 0$, both numerator and denominator approach 0, so it''s $\frac{0}{0}$ form. Apply L''Hopital''s Rule: differentiate numerator and denominator. $\frac{d}{dx}\sin(3x) = 3\cos(3x)$, $\frac{d}{dx}\tan(5x) = 5\sec^2(5x)$. Now limit becomes $\lim_{x \to 0} \frac{3\cos(3x)}{5\sec^2(5x)} = \frac{3 \cdot 1}{5 \cdot 1} = \frac{3}{5}$.', '["Step 1: Confirm indeterminate form $\\frac{0}{0}$ as $x \\to 0$.", "Step 2: Apply L''Hopital''s Rule.", "Step 3: Differentiate numerator: $3\\cos(3x)$", "Step 4: Differentiate denominator: $5\\sec^2(5x)$", "Step 5: Evaluate limit: $\\frac{3\\cdot1}{5\\cdot1} = \\frac{3}{5}$"]', '$\lim_{x \to 0} \frac{f(x)}{g(x)} = \lim_{x \to 0} \frac{f''(x)}{g''(x)}$', 'math.limits.lhopital_wrong_derivative', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:08:12.991Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b376ea9d5f29f250a0a173737aec139', 'NEET', '11', 'Biology', 'bio_12_neet_cell_wall', 'Cell Biology', 'Cell wall composition – primary vs secondary', '[]', '["secondary cell wall","cellulose","dicot stems","plant anatomy","polysaccharide composition"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which polysaccharide is the predominant component of the secondary cell wall in the stems of dicotyledonous plants?', '["Cellulose", "Pectin", "Hemicellulose", "Lignin"]', 'Cellulose', 'The secondary cell wall is rich in cellulose microfibrils, which provide tensile strength. Although lignin is also present, the main polysaccharide is cellulose.', '["Step 1: Identify the major structural polysaccharide in plant secondary walls.", "Step 2: Recall that cellulose forms the load‑bearing framework.", "Step 3: Distinguish cellulose from other wall components such as pectin and hemicellulose."]', '', 'bio.cellwall.secondary_composition', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:27.503Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b3aa26baf70e49b7ecc11d5bda74cdf', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vectors', 'Vectors', 'Resultant magnitude', '[]', '["vector addition","magnitude of resultant","cosine rule","direction"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_MAINS_HARD', 5, -1.0, 'Two vectors $\vec{A}$ and $\vec{B}$ have magnitudes $5\ \text{units}$ and $12\ \text{units}$ respectively, and the angle between them is $60^{\circ}$. Find the magnitude of the resultant vector $\vec{R}=\vec{A}+\vec{B}$.', '["13 units", "15 units", "17 units", "19 units"]', '15 units', 'Using the cosine rule for vector addition: $|\vec{R}|=\sqrt{A^2+B^2+2AB\cos\theta}=\sqrt{5^2+12^2+2\times5\times12\times\cos60^{\circ}}=\sqrt{229}\approx15.13$, which rounds to 15 units.', '["Step 1: Write the cosine rule for the resultant magnitude: $|\\vec{R}|=\\sqrt{A^2+B^2+2AB\\cos\\theta}$.", "Step 2: Substitute $A=5$, $B=12$, $\\cos60^{\\circ}=0.5$.", "Step 3: Compute the expression: $\\sqrt{25+144+60}=\\sqrt{229}$.", "Step 4: Approximate $\\sqrt{229}\\approx15.13$.", "Step 5: Choose the nearest option, 15 units."]', '$|\vec{R}| = \sqrt{A^2 + B^2 + 2AB\cos\theta}$', 'math.vector.addition.resultant_magnitude', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:42:41.912Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b3c67952b385d05a65e2c1b39a30d14', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_electrostatics', 'Electric Charges and Fields', 'Electrostatics Advanced', '["phy_12_ja_capacitance"]', '["capacitors","charge conservation","parallel plate capacitor","variable separation","capacitance change","charge redistribution","isolated system"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -2.0, 'Two identical parallel plate capacitors are connected to a battery. If the separation between plates of one capacitor is doubled while the other is halved, the ratio of final total charge to initial total charge is', '["0.5", "1.0", "1.5", "2.0"]', '1.0', 'Charge redistributes such that total charge remains conserved; battery maintains constant voltage.', '["Step 1: Initial charge = 2C₀V", "Step 2: Final capacitances: C₀/2 and 2C₀ → total C = 2.5C₀", "Step 3: Final charge = 2.5C₀V ≠ initial → but battery disconnected? No → V fixed → Q = CV → total Q changes? Wait: battery remains connected → V constant → total Q proportional to total C. But question implies charge redistribution after disconnection? Rethink.", "Wait: if battery stays connected, V fixed, C_total changes → Q_total changes. But answer is 1.0 only if isolated system. Contradiction.", "Actually: standard interpretation — capacitors remain connected to battery → V constant. Then Q_total ∝ C_total. Initial C_total = 2C. Final: C/2 + 2C = 2.5C → Q_final/Q_initial = 2.5/2 = 1.25 → not in options.", "Alternative: system isolated after charging → total charge conserved. Then separation changed → capacitances change → but no battery → total charge same → ratio = 1.0.", "Correct interpretation: charge redistribution in isolated system → total charge conserved.", "Answer: 1.0"]', 'Q_{\text{total}} = \text{constant (isolated)}', 'physics.electrostatics.charge_conservation_misconception', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:49:58.901Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b3edc0395544e6fb9301cfd57bc0a8c', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Coefficient of Performance (COP) of Refrigerator', '[]', '["COP","refrigerator","heat extraction","work input","thermodynamic cycles"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A refrigerator operates between an interior temperature of $300\,\text{K}$ and an exterior temperature of $310\,\text{K}$. During each cycle it extracts $500\,\text{kJ}$ of heat from the interior and does $150\,\text{kJ}$ of work on the system. What is the coefficient of performance (COP) of the refrigerator?', '["3.33", "2.50", "1.67", "0.75"]', '3.33', 'COP for a refrigerator is defined as $\text{COP}=\dfrac{Q_{\text{c}}}{W}$, where $Q_{\text{c}}$ is the heat removed from the cold reservoir and $W$ is the work input. Substituting the given values gives $\text{COP}=\dfrac{500}{150}=3.33$.', '["Step 1: Write the formula for COP of a refrigerator: $\\text{COP}=\\dfrac{Q_{c}}{W}$.", "Step 2: Substitute $Q_{c}=500\\,\\text{kJ}$ and $W=150\\,\\text{kJ}$.", "Step 3: Perform the division $500/150=3.33$."]', 'COP = Q_c / W', 'physics.thermo.cop_calculation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:38.265Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b4083fa32be415ac4823d4c30a3dcd3', 'NEET', '11', 'Biology', 'bio_11_neet_biomolecules', 'Biomolecules', 'Nucleic acid structure', '[]', '["DNA backbone","phosphodiester linkage","nucleotide polymerisation","structural biochemistry"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which type of bond links successive nucleotides in a DNA molecule?', '["Hydrogen bond", "Phosphodiester bond", "Glycosidic bond", "Peptide bond"]', 'Phosphodiester bond', 'In DNA, nucleotides are connected by phosphodiester bonds between the 3'' carbon of one sugar and the 5'' carbon of the next, forming the backbone.', '["Step 1: Identify the backbone of DNA as a sugar‑phosphate chain.", "Step 2: Recognise that the linkage is a phosphodiester bond.", "Step 3: Distinguish it from hydrogen bonds (base pairing) and glycosidic bonds (base‑sugar link)."]', '', 'biology.biomolecules.dna_backbone', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:45:32.085Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b45ac119a75ebc9b98f173d0042b0a7', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_complex_geometry', 'Complex Numbers as Geometry', 'Equilateral triangle condition on complex plane', '["math_12_ja_algebra_identities","math_12_ja_roots_of_unity"]', '["complex numbers","equilateral triangle","rotation in complex plane","cube roots of unity","algebraic identity","geometric condition","symmetry"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'Let $ z_1, z_2, z_3 $ be three distinct complex numbers representing the vertices of a triangle in the complex plane. The triangle is equilateral if and only if:
$$
|z_1 - z_2| = |z_2 - z_3| = |z_3 - z_1|
$$
and
$$
z_1^2 + z_2^2 + z_3^2 = z_1z_2 + z_2z_3 + z_3z_1.
$$
Which of the following conditions is **equivalent** to the triangle being equilateral?', '["$ z_1 + \\omega z_2 + \\omega^2 z_3 = 0 $, where $ \\omega $ is a non-real cube root of unity", "$ (z_1 - z_2)^2 + (z_2 - z_3)^2 + (z_3 - z_1)^2 = 0 $", "$ z_1^2 + z_2^2 + z_3^2 - z_1z_2 - z_2z_3 - z_3z_1 = 0 $", "$ \\frac{z_1 - z_3}{z_2 - z_3} = e^{i\\pi/3} $ or $ e^{-i\\pi/3} $"]', '["[\"$ Z_1 + \\OMEGA Z_2 + \\OMEGA^2 Z_3 = 0 $, WHERE $ \\OMEGA $ IS A NON-REAL CUBE ROOT OF UNITY\",\"$ Z_1^2 + Z_2^2 + Z_3^2 - Z_1Z_2 - Z_2Z_3 - Z_3Z_1 = 0 $\",\"$ \\FRAC{Z_1 - Z_3}{Z_2 - Z_3} = E^{I\\PI/3} $ OR $ E^{-I\\PI/3} $\"]"]', 'An equilateral triangle in the complex plane satisfies rotational symmetry. Using cube roots of unity, $ 1 + \omega + \omega^2 = 0 $, rotation by $ 120^\circ $ implies $ z_1 - z_3 = (z_2 - z_3)e^{\pm i\pi/3} $. The identity $ z_1^2 + z_2^2 + z_3^2 = z_1z_2 + z_2z_3 + z_3z_1 $ is algebraically equivalent. The sum involving $ \omega $ encodes cyclic rotation. Option B is incorrect because it expands to twice the sum of squared differences, not zero.', '["Step 1: Recall that rotating one vertex around another by $ 60^\\circ $ gives equilateral triangle condition.", "Step 2: Use identity $ z_1^2 + z_2^2 + z_3^2 - z_1z_2 - z_2z_3 - z_3z_1 = \\frac{1}{2}[(z_1 - z_2)^2 + (z_2 - z_3)^2 + (z_3 - z_1)^2] $", "Step 3: Recognize that $ z_1 + \\omega z_2 + \\omega^2 z_3 = 0 $ implies cyclic symmetry under $ 120^\\circ $ rotation.", "Step 4: Verify $ \\frac{z_1 - z_3}{z_2 - z_3} = e^{\\pm i\\pi/3} $ corresponds to angle $ 60^\\circ $ at $ z_3 $.", "Step 5: Reject Option B: it simplifies to $ 2[(z_1 - z_2)^2 + (z_2 - z_3)^2 + (z_3 - z_1)^2] \\neq 0 $."]', 'z_1^2 + z_2^2 + z_3^2 = z_1z_2 + z_2z_3 + z_3z_1', 'math.complex.geometry.rotation_magnitude_confusion', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:07:35.885Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b467aa0a296e4f140d3e4d7cf7711ef', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Simple pendulum period conditions', '["phy_11_jm_gravitation"]', '["simple pendulum","time period","gravity variation","proportionality","planetary physics"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A simple pendulum has time period $T$ on Earth. If it is taken to a planet with same density as Earth but twice the radius, what is its new period?', '["$T$", "$\\sqrt{2}T$", "$2T$", "$T/\\sqrt{2}$"]', '$\sqrt{2}T$', '$g \propto R$ for constant density; $T \propto 1/\sqrt{g} \Rightarrow T'' = T\sqrt{2}$', '["$g \\propto R$ at constant density", "$T \\propto 1/\\sqrt{g}$", "$R'' = 2R \\Rightarrow g'' = 2g \\Rightarrow T'' = \\sqrt{2}T$"]', '$T = 2\pi\sqrt{\frac{l}{g}}$', 'physics.oscillations.g_variation_with_radius', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:05:42.507Z', 1);
