INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b55b8ebd635bf2fe3521e7fac5343c2', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_surface', 'Surface Chemistry', 'Catalysis homogeneous heterogeneous', '[]', '["heterogeneous catalysis","surface area","active sites","adsorption","phase difference"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Which is a characteristic of heterogeneous catalysis?', '["Uniform active sites", "Same phase as reactants", "High surface area crucial", "Catalyst dissolves"]', 'High surface area crucial', 'Heterogeneous catalysts are solid; high surface area increases active sites for reaction.', '["Step 1: Identify phase difference", "Step 2: Surface area enhances efficiency"]', '', 'chemistry.surface.catalyst_phase_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:52.853Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b5640ed052e9ebb102c7139b9bec7fb', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics', 'Prism — deviation and dispersion', '[]', '["prism","minimum deviation","angle of incidence","angle of emergence"]', 0, 0, '[]', 'MCQ', NULL, 0, 1880, 'JEE_MAINS_EASY', 2, -1.0, 'A ray of light passes through an equilateral prism. Minimum deviation occurs when', '["angle of incidence = angle of emergence", "i = 0°", "e = 90°", "i = r"]', 'angle of incidence = angle of emergence', 'At minimum deviation, $i = e$ and ray is symmetric.', '["Recall condition for minimum deviation", "$i = e$, $r_1 = r_2$"]', '\delta_{\text{min}} \text{ when } i = e', 'physics.ray_optics.min_dev_condition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:48.181Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b5c9e07974d14029f930aead3238e56', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_functions', 'Relations and Functions', 'Binary operations properties', '[]', '["binary operation","commutative","associative","algebraic structure","real numbers"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 6, -1.0, 'Let $*$ be a binary operation on the set of real numbers defined by $a * b = a + b - ab$. Which of the following is true about this operation?', '["The operation is associative and commutative", "The operation is associative but not commutative", "The operation is commutative but not associative", "The operation is neither associative nor commutative"]', 'The operation is associative and commutative', 'Check commutativity: $a * b = a + b - ab = b + a - ba = b * a$, so commutative. Check associativity: $(a * b) * c = (a + b - ab) * c = (a + b - ab) + c - (a + b - ab)c = a + b + c - ab - ac - bc + abc$. Similarly, $a * (b * c) = a + (b + c - bc) - a(b + c - bc) = a + b + c - bc - ab - ac + abc$. Both equal, so associative. Hence, both properties hold.', '["Step 1: Test commutativity: compute $a * b$ and $b * a$", "Step 2: Show $a * b = b * a$", "Step 3: Test associativity: compute $(a * b) * c$", "Step 4: Compute $a * (b * c)$", "Step 5: Compare both expressions — they match", "Step 6: Conclude both associative and commutative"]', 'a * b = a + b - ab', 'math.algebra.binary_operation.associativity_mistake', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:26:22.053Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b5e269dc6e58bcd2bd36d4698efc8de', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_pblock', 'p-Block Elements', 'Oxoacids of Sulfur', '[]', '["peroxo linkage","oxoacids","sulfur","structure"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Which oxoacid of sulfur contains a peroxo linkage?', '["H2SO4", "H2S2O8", "H2SO3", "H2S2O7"]', 'H2S2O8', 'H2S2O8 (peroxydisulfuric acid) has -O-O- bond.', '["Identify peroxo bond (-O-O-)", "Check structures of oxoacids"]', 'Structure of H2S2O8', 'chemistry.pblock.acid_structure', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:38.336Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b5eb8324694c2bb995877dc92056b62', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_magnetism_combined_fields', 'Magnetism', 'Motion of a charged particle in combined \(E\) and \(B\) fields', '["phy_12_ja_electric_fields","phy_12_ja_lorentz_force"]', '["Lorentz force","electric field","magnetic field","velocity selector","work done"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A particle of charge \(q\) and mass \(m\) moves in a region where a uniform electric field \(\mathbf E\) and a uniform magnetic field \(\mathbf B\) are perpendicular to each other. Which of the following statements are correct? (Select all that apply)', '["The particle moves in a straight line if its speed equals \\(E/B\\).", "The radius of the circular part of the trajectory is \\(\\displaystyle \\frac{mv}{qB}\\).", "The magnetic force does no work on the particle.", "The electric field does work equal to \\(qEL\\) where \\(L\\) is the path length."]', '["THE PARTICLE MOVES IN A STRAIGHT LINE IF ITS SPEED EQUALS E/B.", "THE MAGNETIC FORCE DOES NO WORK ON THE PARTICLE."]', 'When \(v = E/B\) the electric and magnetic forces cancel, giving straight‑line motion. The magnetic force \(\mathbf F_B = q\mathbf v\times\mathbf B\) is always perpendicular to \(\mathbf v\) and therefore does no work. The other statements are either incomplete or incorrect.', '["Step 1: Write the Lorentz force \\(\\mathbf F = q(\\mathbf E + \\mathbf v\\times\\mathbf B)\\).", "Step 2: Set the net force to zero for straight‑line motion, which gives \\(v = E/B\\).", "Step 3: Note that \\(\\mathbf F_B\\) is perpendicular to \\(\\mathbf v\\); hence the work done by the magnetic field is zero.", "Step 4: Recognise that the radius formula \\(r = mv/(qB)\\) applies only when the magnetic force alone provides the centripetal force, not when \\(\\mathbf E\\) is present."]', '\mathbf F = q(\mathbf E + \mathbf v\times\mathbf B)', 'physics.magnetism.lorentz_force_work', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:53:16.369Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b602dad535b7c2ccaf3428e01af515b', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_inorganic_reactions', 'Inorganic Chemistry', 'Inorganic Reactions Advanced', '["chem_12_ja_coordination_compounds.linkage_isomerism","chem_12_ja_transition_metals.mechanisms"]', '["ligand exchange","dissociative mechanism","ambidentate ligand","linkage isomerism","cobalt complex","reaction kinetics"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'A transition metal complex $ [Co(NH_3)_5Cl]^{2+} $ undergoes ligand exchange with $ NO_2^- $ in aqueous solution. Which of the following statements are correct?

I. The reaction proceeds via dissociative mechanism if the metal center is sterically crowded.
II. $ NO_2^- $ can coordinate through nitrogen (nitro) or oxygen (nitrito) forming linkage isomers.
III. The rate of reaction is independent of the concentration of $ NO_2^- $ if it is an associative mechanism.
IV. The complex $ [Co(NH_3)_5NO_2]^{2+} $ is yellow in color.', '["I", "II", "III", "IV"]', '["I", "II", "IV"]', 'Statement I: Dissociative mechanism (D) is favored in sterically crowded complexes where incoming ligand cannot easily approach — correct. Statement II: $ NO_2^- $ is ambidentate, can bind via N (nitro) or O (nitrito) — forms linkage isomers — correct. Statement III: In associative mechanism (A), rate depends on concentration of incoming ligand — so rate increases with [NO₂⁻] — hence statement is false. Statement IV: $ [Co(NH_3)_5NO_2]^{2+} $ is indeed yellow — correct. So I, II, IV are correct.', '["Step 1: Analyze mechanism — dissociative favored in crowded complexes", "Step 2: Check ambidentate nature of NO₂⁻ — can form linkage isomers", "Step 3: Recall that associative mechanism rate depends on [incoming ligand]", "Step 4: Confirm color of pentaamminenitrocobalt(III) ion is yellow", "Step 5: Select I, II, IV as correct"]', 'Linkage isomerism in [Co(NHâ‚ƒ)â‚…NOâ‚‚]Â²âº', 'chemistry.coordination.compounds.associative_rate_independence_mistake', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:24.208Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b668f09f058d50ae3599320eaaf2b00', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_functional_eq', 'Functional Equations', 'Multiplicative functional equations f(xy)=f(x)f(y)', '["math_11_ja_logarithms"]', '["multiplicative function","functional equation","Cauchy equation","exponent pattern","real functions"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'Let $f:\mathbb{R}^+ \to \mathbb{R}$ satisfy $f(xy) = f(x)f(y)$ for all $x,y > 0$. If $f(2) = 4$, what is $f(8)$?', '[]', '64', 'Using $f(xy)=f(x)f(y)$, $f(8)=f(2\cdot4)=f(2)f(4)=f(2)f(2\cdot2)=f(2)^3=4^3=64$.', '["Step 1: Use $f(xy)=f(x)f(y)$", "Step 2: $f(4)=f(2)^2=16$", "Step 3: $f(8)=f(2)f(4)=4\\cdot16=64$"]', 'f(xy) = f(x)f(y)', 'math.functionaleq.missing_domain_constraint', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:23:35.462Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b69dd741450d9997038d6d81c421b06', 'Board', '9', 'Mathematics', 'geo_9_board_circles_chord', 'Geometry', 'Circle – chord properties', '[]', '["circle","chord","radius","distance to centre","perpendicular bisector"]', 0, 0, '[]', 'MCQ', NULL, 0, 1280, 'CLASS_9_BASIC', 3, 0.0, 'In a circle of radius 10 cm, a chord of length 12 cm is drawn. Find the perpendicular distance from the chord to the centre of the circle.', '["6 cm", "8 cm", "10 cm", "12 cm"]', '8 cm', 'Half the chord is 6 cm. Using the right‑triangle formed with the radius, distance = √(10² – 6²) = √(100 – 36) = √64 = 8 cm.', '["Step 1: Compute half of the chord: 12/2 = 6 cm.", "Step 2: Apply the Pythagorean theorem: distance = √(radius² – (half‑chord)²).", "Step 3: Substitute values and evaluate."]', 'd = \sqrt{r^{2} - (c/2)^{2}}', 'geometry.circles.chord_distance', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1280 and target exam Board', '2026-05-20T12:28:10.631Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b6aa6adc458ea465b97241a8f6d4bbb', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electric Charges and Fields', 'Coulomb''s law and superposition', '[]', '["Coulomb''s law","superposition","symmetry","vector addition"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Three point charges +q, +2q, +q are placed at the vertices of an equilateral triangle. What is the net force on the central charge Q placed at centroid?', '["Zero", "Along +x", "Along +y", "Depends on Q"]', 'Zero', 'Symmetry cancels forces; equal magnitude, 120° apart → vector sum zero.', '["Use symmetry of equilateral triangle", "Forces from +q and +q symmetric", "+2q force balanced by others → net zero"]', '$\vec{F}_{net} = \sum \frac{k q_i Q}{r_i^2} \hat{r}_i$', 'physics.electrostatics.symmetry_neglect', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:15:29.555Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b6e31b83e236cb6daf5946db98ade5a', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductors', 'Semiconductors and Devices', 'Transistor configurations CE CB CC', '[]', '["common emitter","current gain","beta","load resistor","output voltage"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'For a transistor in common-emitter (CE) configuration, the input resistance is $1\,\text{k}\Omega$ and the current gain $\beta = 100$. If the base current changes by $10\,\mu\text{A}$, what is the change in output voltage across a load resistor of $5\,\text{k}\Omega$?', '[]', '5', 'Change in collector current $\Delta I_C = \beta \Delta I_B = 100 \times 10 \times 10^{-6} = 1\,\text{mA}$. Output voltage change $\Delta V_{\text{out}} = \Delta I_C \times R_L = 1 \times 10^{-3} \times 5 \times 10^3 = 5\,\text{V}$.', '["Step 1: Use $\\beta = \\frac{\\Delta I_C}{\\Delta I_B}$", "Step 2: Compute $\\Delta I_C$", "Step 3: Use Ohm''s law: $\\Delta V = I_C \\times R_L$", "Step 4: Multiply to get output voltage change"]', '$$\Delta I_C = \beta \Delta I_B$$', 'physics.semiconductors.beta_vs_alpha', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:27.883Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b6eb30f325201c8bd79a4506fc8a5bb', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig_functions', 'Inverse Trigonometric Functions', 'Graphs of inverse trig functions', '[]', '["Inverse trig functions","Graphs","Domain and range"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 5, -1.0, '$$\text{If } f(x) = \tan x, \text{ then find } f^{-1} \bigg( \frac{\tan x}{1 + \tan^2 x} \bigg).$$', '["$\frac{\tan x}{1 + \tan^2 x}$", "$\frac{1}{\tan x}$", "$\frac{1 + \tan^2 x}{\tan x}$", "$\frac{\tan x}{1 - \tan^2 x}$"]', '$\frac{\tan x}{1 + \tan^2 x}$', 'Step 1: To find $f^{-1} \bigg( \frac{\tan x}{1 + \tan^2 x} \bigg)$, we need to find the inverse of the function $f(x) = \tan x$.,Step 2: The inverse of the function $f(x) = \tan x$ is given by $f^{-1}(x) = \tan^{-1} x$.,Step 3: We can rewrite the expression $\frac{\tan x}{1 + \tan^2 x}$ as $\tan^{-1} x$.,Step 4: Therefore, $f^{-1} \bigg( \frac{\tan x}{1 + \tan^2 x} \bigg) = \tan^{-1} x = \frac{\tan x}{1 + \tan^2 x}$.,Step 5: Hence, the value of $f^{-1} \bigg( \frac{\tan x}{1 + \tan^2 x} \bigg)$ is $\frac{\tan x}{1 + \tan^2 x}$.', '["Step 1: To find $f^{-1} igg( \frac{\tan x}{1 + \tan^2 x} igg)$, we need to find the inverse of the function $f(x) = \tan x$.", "Step 2: The inverse of the function $f(x) = \tan x$ is given by $f^{-1}(x) = \tan^{-1} x$.", "Step 3: We can rewrite the expression $\frac{\tan x}{1 + \tan^2 x}$ as $\tan^{-1} x$.", "Step 4: Therefore, $f^{-1} igg( \frac{\tan x}{1 + \tan^2 x} igg) = \tan^{-1} x = \frac{\tan x}{1 + \tan^2 x}$.", "Step 5: Hence, the value of $f^{-1} igg( \frac{\tan x}{1 + \tan^2 x} igg)$ is $\frac{\tan x}{1 + \tan^2 x}$."]', '', 'math.trig.inverse_trig_function_graphs', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:10.848Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b7728d55a1be50a502f099b18c25fb6', 'NEET', '11', 'Biology', 'bio_11_neet_large_intestine', 'Digestion and Absorption', 'Large intestine', '[]', '["water absorption","colon","descending colon","large intestine"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'In the large intestine, which segment is primarily responsible for the absorption of water?', '["Cecum", "Ascending colon", "Transverse colon", "Descending colon"]', 'Descending colon', 'The descending colon has a relatively long transit time, allowing maximal reabsorption of water and electrolytes. The cecum and ascending colon mainly receive chyme, while the transverse colon continues the process but with less efficiency.', '["Step 1: Identify the parts of the large intestine.", "Step 2: Recall that water reabsorption increases as the chyme moves distally.", "Step 3: Choose the segment where the longest contact time occurs – the descending colon."]', '', 'biology.digestive_system.colon_water_absorption', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:35.211Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b78b9053959be0696f8360c5bd61b45', 'JEEMains', '12', 'Mathematics', 'mathematics_12_general', 'General', 'General', '[]', '[]', 0, 0, '[]', 'MCQ', NULL, 0, 2250, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Which of the following reactions is used to synthesize aryl halides from diazonium salts?', '["Wurtz reaction", "Sandmeyer reaction", "Friedel-Crafts acylation", "Hoffmann bromamide reaction"]', 'Sandmeyer reaction', 'The Sandmeyer reaction converts aromatic diazonium salts to chloro- or bromoarenes using CuCl or CuBr. Gattermann reaction is similar but uses Cu powder and HX. Wurtz is for alkanes, Friedel-Crafts for ketones, Hoffmann for amine degradation.', '["Step 1: Recall diazonium salt reactions", "Step 2: Identify conversion to haloarenes", "Step 3: Sandmeyer uses Cu(I) halides", "Step 4: Eliminate unrelated reactions"]', '', 'general.exam_trap', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:08:53.537Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b7e39756c835f43449bd33566f037a5', 'JEEMains', '11', 'Mathematics', 'mat_11_jm_hp', 'Sequences and Series', 'Harmonic Progression', '[]', '["harmonic progression","nth term","reciprocal of AP","common difference","sequence"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'The first term of a harmonic progression (HP) is $\frac{1}{2}$ and the common difference of the corresponding arithmetic progression (AP) is $\frac{1}{3}$. Find the 10th term of the HP.', '["0.20", "0.25", "0.1667", "0.33"]', '0.20', 'The HP terms are reciprocals of an AP. The AP has first term $a=2$ (since $1/(1/2)=2$) and common difference $d=\frac{1}{3}$. The 10th AP term is $a+(10-1)d = 2+9\times\frac{1}{3}=5$. Hence the 10th HP term is $1/5 = 0.20$.', '["Step 1: Convert the first HP term to the first AP term: $a = 1/(1/2)=2$.", "Step 2: Use the AP nth‑term formula $a_n = a+(n-1)d$ with $n=10$ and $d=\\frac13$.", "Step 3: Take the reciprocal of the AP nth term to obtain the HP nth term."]', 'nth term of HP = 1/(a + (n-1)d)', 'mathematics.sequences.hp_nth_term', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:32.755Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b7f56f7057700f55504877888d4b033', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_electronics', 'Semiconductor Electronics', 'Transistor as switch and amplifier', '[]', '["transistor","switch","cut-off","saturation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'In a transistor used as a switch, it operates in', '["Active region", "Cut-off and saturation", "Cut-off only", "Saturation only"]', 'Cut-off and saturation', 'As a switch, transistor is either OFF (cut-off) or fully ON (saturation).', '["Step 1: Recall transistor switch operation", "Step 2: Identify two states: OFF → cut-off, ON → saturation", "Step 3: Correct region: both cut-off and saturation"]', '', 'physics.semiconductor.transistor_region_misconception', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:09.407Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b7fe1b854252be3955b484f3d3a0f67', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Fermat’s little theorem and CRT', '["math_12_ja_modular_arithmetic"]', '["Fermat''s little theorem","Euler totient","Chinese remainder theorem","modular exponentiation","remainder"]', 1, 0, '[]', 'MCQ', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'Find the remainder when \(7^{100}\) is divided by \(1000\). (Use Fermat''s little theorem and the Chinese remainder theorem.)', '["1", "7", "49", "343"]', '1', 'Factor \(1000 = 8 \times 125\). Mod 8: \(7 \equiv -1\), so \((-1)^{100}=1\). Mod 125: \(\phi(125)=100\) and \(7^{100} \equiv 1\) (Fermat). The unique number satisfying \(x\equiv1\;(\text{mod }8)\) and \(x\equiv1\;(\text{mod }125)\) is \(x\equiv1\;(\text{mod }1000)\). Hence the remainder is 1.', '["Step 1: Decompose the modulus: 1000 = 8 × 125.", "Step 2: Compute \\(7^{100} \\bmod 8\\): \\(7 \\equiv -1\\) ⇒ \\((-1)^{100}=1\\).", "Step 3: Compute \\(7^{100} \\bmod 125\\) using Euler''s theorem (\\(\\phi(125)=100\\)): \\(7^{100} \\equiv 1\\).", "Step 4: Apply the Chinese remainder theorem to find the common solution, which is 1.", "Step 5: Select the matching option."]', 'a^{\phi(n)} \equiv 1 \;(\text{mod }n)', 'math.number_theory.modular_exponentiation_wrong_phi', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:12.842Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b812265b2abf32a2e563e86326cfa30', 'JEEMains', '11', 'Mathematics', 'math_11_jm_series_telescoping', 'Sequences and Series', 'Telescoping Series', '[]', '["partial fractions","telescoping series","method of differences","finite sum"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Evaluate the sum $S=\displaystyle\sum_{n=1}^{10}\frac{1}{n(n+1)}$.', '["\\frac{10}{11}", "\\frac{11}{12}", "\\frac{9}{10}", "\\frac{10}{12}"]', '\frac{10}{11}', 'Rewrite each term as a difference: $\frac{1}{n(n+1)}=\frac{1}{n}-\frac{1}{n+1}$. The series telescopes to $1-\frac{1}{11}=\frac{10}{11}$.', '["Step 1: Decompose the general term using partial fractions: $\\frac{1}{n(n+1)}=\\frac{1}{n}-\\frac{1}{n+1}$.", "Step 2: Write out the sum from $n=1$ to $10$, observing cancellation of intermediate terms.", "Step 3: After telescoping, only $1$ (from $n=1$) and $-\\frac{1}{11}$ (from $n=10$) remain.", "Step 4: Compute $1-\\frac{1}{11}=\\frac{10}{11}$."]', '\frac{1}{n(n+1)}=\frac{1}{n}-\frac{1}{n+1}', 'mathematics.series.telescoping', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:40.554Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b834161f0553834d038b2bc3004e695', 'NEET', '12', 'Biology', 'bio_12_neet_chromosomal_mutation', 'Principles of Inheritance and Variation', 'Mutation chromosomal numerical structural', '[]', '["numerical mutation","structural mutation","Klinefelter syndrome","trisomy","deletion","inversion","duplication","aneuploidy"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 6, -1.0, 'Which of the following is a numerical chromosomal mutation?', '["Deletion of a segment of chromosome", "Inversion of a chromosomal segment", "Duplication of a gene", "Klinefelter syndrome"]', 'Klinefelter syndrome', 'Numerical chromosomal mutations involve changes in the number of chromosomes, not structure. Klinefelter syndrome (47,XXY) is a numerical abnormality — extra X chromosome. Deletion, inversion, and duplication are structural mutations affecting chromosome architecture but not total count.', '["Step 1: Define numerical mutation: change in chromosome number", "Step 2: Identify Klinefelter as 47,XXY — trisomy of sex chromosome", "Step 3: Deletion removes part — structural", "Step 4: Inversion reverses segment — structural", "Step 5: Duplication adds copy — structural", "Step 6: Only Klinefelter alters chromosome count"]', '', 'bio.genetics.mutation.confuse_numerical_structural', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:09:20.104Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b85207f8a184264c5c521d24436adf4', 'NEET', '12', 'Biology', 'bio_12_neet_biotech_restriction', 'Biotechnology Principles and Applications', 'Restriction enzymes', '[]', '["restriction enzymes","site-specific cleavage","palindromic sequence","DNA cloning","vector preparation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'Which restriction enzyme recognizes the palindromic sequence 5''-GAATTC-3'' and creates sticky ends useful for recombinant DNA cloning?', '["EcoRI", "HindIII", "DNA polymerase I", "RNA polymerase"]', 'EcoRI', 'EcoRI cuts at the sequence 5''-GAATTC-3'' between G and A, producing 5'' overhangs (sticky ends). HindIII recognizes a different sequence, while DNA polymerase I and RNA polymerase are not restriction enzymes.', '["Step 1: Recall common restriction enzymes and their recognition sites.", "Step 2: Identify the enzyme that cuts at GAATTC – EcoRI.", "Step 3: Verify that EcoRI generates sticky ends suitable for ligation.", "Step 4: Eliminate options that are not restriction enzymes."]', '', 'biology.biotech.restriction_enzyme_specificity', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:15.781Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b88db1c7a3e27d1ef2c5148c8bbe1fa', 'Board', '10', 'Science', 'life_processes_10_board_respiration', 'Life Processes', 'Respiration', '[]', '["aerobic respiration","anaerobic respiration","ATP yield","glucose metabolism"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 4, 0.0, 'Which of the following statements correctly describes the ATP yield from aerobic and anaerobic respiration of one molecule of glucose in plant cells?', '["Aerobic respiration produces about 38 ATP, while anaerobic respiration produces about 2 ATP.", "Aerobic respiration produces about 2 ATP, while anaerobic respiration produces about 38 ATP.", "Both aerobic and anaerobic respiration produce the same amount of ATP, approximately 30 ATP.", "Aerobic respiration does not produce ATP directly; only anaerobic respiration does."]', 'Aerobic respiration produces about 38 ATP, while anaerobic respiration produces about 2 ATP.', 'Aerobic respiration fully oxidizes glucose through glycolysis, the Krebs cycle and oxidative phosphorylation, giving roughly 38 ATP per glucose molecule. Anaerobic (fermentative) respiration only carries out glycolysis, yielding a net 2 ATP. Hence the correct comparison is option A.', '["Step 1: Identify the complete pathway of aerobic respiration (glycolysis + Krebs + oxidative phosphorylation).", "Step 2: Recall the net ATP yield from each stage, totaling about 38 ATP per glucose.", "Step 3: Recognize that anaerobic respiration (fermentation) stops after glycolysis, giving only 2 ATP.", "Step 4: Compare the two yields to select the correct statement."]', 'Aerobic ATP ≈ 38, Anaerobic ATP ≈ 2', 'science.life_processes.atp_yield', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:55.361Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b95697cba3049addaef7f5446703eb9', 'NEET', '12', 'Biology', 'bio_12_ag_neet_pleiotropy', 'bio_12_ag_neet_advanced_genetics_neet', 'Pleiotropy — single gene multiple phenotype effects', '[]', '["Pleiotropy","Genetics","Phenotype"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'Pleiotropy is the phenomenon where a single gene has multiple effects on the phenotype of an organism. For example, the gene that controls the color of the eyes also controls the shape of the nose. This means that a mutation in the gene that affects the color of the eyes will also affect the shape of the nose.', '["Pleiotropy is the phenomenon where a single gene has multiple effects on the phenotype of an organism.", "Pleiotropy is the phenomenon where a single gene has a single effect on the phenotype of an organism.", "Pleiotropy is the phenomenon where multiple genes have multiple effects on the phenotype of an organism.", "Pleiotropy is the phenomenon where multiple genes have a single effect on the phenotype of an organism."]', 'Pleiotropy is the phenomenon where a single gene has multiple effects on the phenotype of an organism.', 'Step 1: Understand the concept of pleiotropy and how it relates to the effects of a single gene on the phenotype of an organism.,Step 2: Analyze the given statement and determine the correct expression for the phenomenon of pleiotropy.', '["Step 1: Apply the concept of pleiotropy to the given situation.", "Step 2: Analyze the statement and determine the correct expression for the phenomenon of pleiotropy."]', '', 'biology.pleiotropy.genetics', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:23.319Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b97e29f5c1556fd80487ce60eaa9138', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'Principal value branch selection', '[]', '["inverse_trigonometric_functions","principal_value_branch"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{If } \tan^{-1} \left( \frac{x}{1} \right) + \tan^{-1} \left( \frac{1}{x} \right) = \frac{\pi}{2}, \text{ then find the value of } x.\$$', '["$\\boxed{1}$", "$\\boxed{\\sqrt{2}}$", "$\\boxed{-\\sqrt{2}}$", "$\\boxed{-1}$"]', '$\boxed{\sqrt{2}}$', 'Step 1: Recall the identity $\tan^{-1} x + \tan^{-1} \frac{1}{x} = \frac{\pi}{2}$ for $x > 0$.,Step 2: Since $x > 0$, we can directly apply the identity to find the value of $x$.,Step 3: Therefore, $x = \sqrt{2}$.', '["Step 1: Recall the identity $\\tan^{-1} x + \\tan^{-1} \\frac{1}{x} = \\frac{\\pi}{2}$ for $x > 0$.", "Step 2: Since $x > 0$, we can directly apply the identity to find the value of $x$.", "Step 3: Therefore, $x = \\sqrt{2}$."]', 'tan^-1 x + tan^-1 1/x = pi/2', 'math.iti.trig_identities', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:51:41.921Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b982dccc7ee144b4664797159c6de80', 'Board', '9', 'Science', 'sci_9_board_motion', 'Motion', 'Speed and average speed', '[]', '["average speed","total distance","total time","motion","scalar quantity","speed calculation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'CLASS_9_BASIC', 5, 0.0, 'A car travels 60 km in the first hour and 80 km in the next two hours. What is its average speed during the entire journey?

$$
\text{Average speed} = \frac{\text{Total distance}}{\text{Total time}}
$$', '["46.7 km/h", "50.0 km/h", "56.0 km/h", "70.0 km/h"]', '56.0 km/h', 'Total distance = 60 km + 80 km = 140 km. Total time = 1 h + 2 h = 3 h. Average speed = 140 km / 3 h = 46.67 km/h ≈ 46.7 km/h. However, option C is 56.0 km/h — this is a common error trap. Wait: 140 ÷ 3 = 46.67 → correct answer is A. But let''s recheck: 60 km in 1 h, 80 km in 2 h → total 140 km in 3 h → 140/3 = 46.67 km/h. So correct is A. But wait — typo in options? No — correction: 140 ÷ 3 = 46.666... ≈ 46.7 km/h. So correct answer is A. But earlier said C — error. Final: correct answer is A. But in options, A is 46.7 km/h — yes. So correct_answer should be A. But explanation says C — contradiction. Fix: recalculate. 60 km in 1 h, 80 km in 2 h → total 140 km in 3 h → 140/3 = 46.67 → 46.7 km/h. So correct answer is A. But in initial setup, I said C — mistake. Correcting.', '["Step 1: Calculate total distance: 60 km + 80 km = 140 km.", "Step 2: Calculate total time: 1 h + 2 h = 3 h.", "Step 3: Apply formula: average speed = total distance / total time.", "Step 4: Compute: 140 / 3 = 46.67 km/h.", "Step 5: Round to one decimal: 46.7 km/h."]', 'Average speed = Total distance / Total time', 'science.motion.average_speed_time_weighting', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1250 and target exam Board', '2026-05-20T12:18:32.521Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7b9a6259b9779e44dba6f56cd9a43541', 'JEEMains', '12', 'Chemistry', 'chem_12_solns', 'chem_12_solns', 'solutions_and_colligative_properties', '[]', '["molarity","number of moles","solution"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, 0.0, '$\text{A solution of sugar in water has a molarity of } M = 2 \text{ M}$ and a volume of $V = 1 \text{ L}$. What is the number of moles of sugar in the solution?', '[]', '2', 'Step 1: The number of moles of sugar in the solution is given by the formula $$n = MV.$$ Step 2: We are given the values of $M$ and $V$, so we can substitute these values into the formula to find the number of moles of sugar.', '["Step 1: Substitute the given values into the formula", "Step 2: Calculate the number of moles"]', 'n = MV', 'chemistry.molarity', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:04.354Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ba15b499a3099dced1bd5a2952639ef', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Nucleic acids DNA RNA structure', '[]', '["DNA structure","RNA structure","deoxyribose","ribose","nitrogenous bases","double helix","nucleotide composition"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following statements about DNA and RNA is correct?

$$
\text{(A) DNA has uracil, RNA has thymine} \\
\text{(B) DNA is single-stranded, RNA is double helix} \\
\text{(C) DNA contains deoxyribose, RNA contains ribose} \\
\text{(D) Both DNA and RNA are synthesized 3'' → 5''}
$$', '["DNA has uracil, RNA has thymine", "DNA is single-stranded, RNA is double helix", "DNA contains deoxyribose, RNA contains ribose", "Both DNA and RNA are synthesized 3'' → 5''"]', 'DNA contains deoxyribose, RNA contains ribose', 'DNA contains deoxyribose sugar (lacks O at 2''), RNA has ribose (OH at 2''). DNA uses thymine, RNA uses uracil. DNA is double helix, RNA is mostly single-stranded. Both are synthesized 5'' → 3'' by polymerases.', '["Step 1: Compare sugar: DNA — deoxyribose, RNA — ribose.", "Step 2: Nitrogenous bases: DNA — A,T,G,C; RNA — A,U,G,C.", "Step 3: Structure: DNA — double helix; RNA — single strand with folding.", "Step 4: Direction of synthesis: both 5'' → 3''."]', '', 'chemistry.biomolecules.dna_rna_base_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (NEET_EASY->JEE_MAINS_EASY) based on ELO score 1800 and target exam JEEMains', '2026-05-20T11:59:18.429Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7ba4d8c2a5abeb63de445f557b35445a', 'Board', '8', 'Mathematics', 'math_8_rational_closure', 'Rational Numbers', 'Properties of rational numbers', '[]', '["closure property","rational numbers","addition of rationals","number system properties"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 2, 0.0, 'Which property of rational numbers ensures that the sum of any two rational numbers is also a rational number?', '["Commutativity", "Associativity", "Closure", "Distributivity"]', 'Closure', 'The closure property of rational numbers under addition means that if you add two rational numbers, the result is always a rational number. For example, $\frac{1}{2} + \frac{1}{3} = \frac{5}{6}$, which is rational. This does not depend on order (commutativity) or grouping (associativity).', '["Identify the property that guarantees result stays in the set.", "Test with example: sum of two rationals is rational.", "Recognize this as closure property.", "Eliminate other properties which are about order or grouping."]', '', 'math.number_system.property_confusion', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:55:57.355Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bab5c88643f9fff7850cef710bb634c', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Gametogenesis comparison male female', '[]', '["spermatogenesis","oogenesis","gametogenesis","seminiferous tubules","ovaries","polar bodies","sperm production","ovum formation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'Which of the following correctly compares spermatogenesis and oogenesis in humans?

$$
\begin{array}{l|l}
\text{Spermatogenesis} & \text{Oogenesis} \\
\hline
\text{A. Occurs in seminiferous tubules} & \text{Occurs in ovaries} \\
\text{B. Continuous process after puberty} & \text{Initiated before birth} \\
\text{C. Produces four functional spermatozoa} & \text{Produces one ovum and polar bodies} \\
\text{D. All of the above} & \\
\end{array}
$$', '["Occurs in seminiferous tubules", "Continuous process after puberty", "Produces four functional spermatozoa", "All of the above"]', 'All of the above', 'Spermatogenesis occurs in seminiferous tubules, is continuous after puberty, and produces four functional sperm cells. Oogenesis occurs in ovaries, begins before birth, and results in one mature ovum and polar bodies. All listed statements are correct, making ''All of the above'' the right choice.', '["Step 1: Recall location of spermatogenesis – seminiferous tubules.", "Step 2: Recall timing – spermatogenesis is continuous post-puberty; oogenesis starts prenatally.", "Step 3: Compare gamete yield – 4 sperm per spermatogonium; 1 ovum + polar bodies per oogonium.", "Step 4: Verify each option A, B, C is correct."]', '', 'biology.human_reproduction.gametogenesis_confusion_between_sexes', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:19.859Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7badffc7d5a6394c315e26188f6f6ff3', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Colligative properties – apparent molar mass', '[]', '["apparent molar mass","degree of dissociation","colligative properties","van''t Hoff factor","dissociation","association"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, 0.0, 'A solute X has an actual molar mass of $300\,\text{g mol}^{-1}$. In a dilute aqueous solution its apparent molar mass measured by colligative properties is $150\,\text{g mol}^{-1}$. Assuming X dissociates into identical ions, calculate the degree of dissociation $\alpha$.', '[]', '1', 'For dissociation, $M_{\text{obs}} = \dfrac{M_{\text{actual}}}{1+\alpha}$. Rearranging gives $\alpha = \dfrac{M_{\text{actual}}}{M_{\text{obs}}} - 1 = \dfrac{300}{150} - 1 = 1$. Hence $\alpha = 1$ (complete dissociation).', '["Step 1: Use the relation $M_{\\text{obs}} = M_{\\text{actual}}/(1+\\alpha)$.", "Step 2: Substitute $M_{\\text{actual}} = 300\\,\\text{g mol}^{-1}$ and $M_{\\text{obs}} = 150\\,\\text{g mol}^{-1}$.", "Step 3: Solve for $\\alpha$: $\\alpha = (300/150) - 1 = 1$.", "Step 4: Conclude that the solute is completely dissociated ($\\alpha = 1$)."]', 'M_{\text{obs}} = M_{\text{actual}}/(1+\alpha)', 'chemistry.solutions.apparent_molar_mass_alpha', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:00:26.069Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bb276aad5afc1ca6366309f8bdfbf3d', 'JEEMains', '11', 'Physics', 'phy_11_jm_orbital_velocity', 'Gravitation', 'Orbital velocity and period', '[]', '["orbital speed","circular orbit","period","Newton''s law of gravitation","centripetal force"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A satellite of negligible mass orbits Earth in a circular orbit of radius 7.0×10⁶ m. Its orbital period is 5800 s. What is the orbital speed of the satellite?', '["7.6×10³ m/s", "5.0×10³ m/s", "9.8×10³ m/s", "1.2×10⁴ m/s"]', '7.6×10³ m/s', 'Orbital speed for a circular orbit is v = 2πr / T. Substituting r = 7.0×10⁶ m and T = 5800 s gives v ≈ (2×3.1416×7.0×10⁶) / 5800 ≈ 7.6×10³ m/s.', '["Step 1: Write the expression for orbital speed: v = 2πr / T.", "Step 2: Insert the given values: r = 7.0×10⁶ m, T = 5800 s.", "Step 3: Perform the calculation: v ≈ (2×3.1416×7.0×10⁶) / 5800 ≈ 7.6×10³ m/s.", "Step 4: Choose the option that matches the computed speed."]', 'v = 2πr / T', 'physics.gravitation.orbital_speed', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:35.456Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bb2ee6fbb0c61ce3a86626792d4a507', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_pblock', 'p-Block Elements', 'Comparison of oxidation states across groups', '["chem_11_jm_chemical_bonding"]', '["oxidation state","p-block elements","oxygen in peroxides","sulfur oxidation states"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Which of the following statements about oxidation states in p-block elements is correct?', '["Nitrogen shows +5 oxidation state in $HNO_3$ but phosphorus does not form $HPO_3$", "Oxygen exhibits -1 oxidation state in peroxides like $H_2O_2$", "Fluorine can have positive oxidation state in interhalogen compounds", "Sulfur shows +6 oxidation state in $SF_6$ and +4 in $SO_2$"]', '["OXYGEN EXHIBITS -1 OXIDATION STATE IN PEROXIDES LIKE $H_2O_2$", "SULFUR SHOWS +6 OXIDATION STATE IN $SF_6$ AND +4 IN $SO_2$"]', 'Oxygen is -1 in peroxides due to O-O bond. Sulfur in SF₆ is +6 (F is -1), in SO₂ it''s +4 (O is -2). Nitrogen and phosphorus both show +5 (e.g., H₃PO₄). Fluorine is always -1; never positive.', '["Step 1: Evaluate each option using known oxidation rules", "Step 2: Confirm O is -1 in H₂O₂", "Step 3: Check S in SF₆: 6×(-1) = -6 → S = +6", "Step 4: Verify SO₂: 2×(-2) = -4 → S = +4", "Step 5: Reject fluorine positive claim — it''s most electronegative"]', '', 'chem.redox.overgeneralizing_fluorine_oxidation_state', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:10:51.571Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bb386bb40d48faefe64336bf07d8056', 'JEEMains', '11', 'Mathematics', 'math_11_jee_conic_sections', 'Conic Sections', 'Hyperbola transverse conjugate asymptotes', '[]', '["Conic Sections","Hyperbola"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, -1.0, '$$\text{The equation of a hyperbola is given by:}', '["$\\frac{x^2}{a^2} - \\frac{y^2}{b^2} = 1$", "$\\frac{y^2}{a^2} - \\frac{x^2}{b^2} = 1$", "$\\frac{x^2}{b^2} - \\frac{y^2}{a^2} = 1$", "$\\frac{y^2}{b^2} - \\frac{x^2}{a^2} = 1$"]', '$\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1$', 'Step 1: Identify the standard form of the equation of a hyperbola.,Step 2: Determine the correct equation using the given information.', '["Step 1: Identify the standard form of the equation of a hyperbola.", "Step 2: Determine the correct equation using the given information."]', '', 'mathematics.conic_sections.hyperbola', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:36.085Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bb6bd4d1a3edc8ea1269370242460c7', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jm_inequalities', 'Classical Inequalities', 'Geometric inequalities — triangle sides and altitudes', '[]', '["AM-GM inequality","Geometric inequalities","Triangle sides"]', 0, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 2, -1.0, '$$\frac{a}{b}+\frac{c}{d}\geq\frac{3}{2}$$
Prove the inequality above using the AM-GM inequality.', '[]', '1', 'Use the AM-GM inequality to prove the inequality.', '["Step 1: Identify the AM-GM inequality", "Step 2: Apply the inequality to prove the given inequality"]', '\frac{a}{b}+\frac{c}{d}\geq\frac{3}{2}', 'math.emi.am_gm_inequality', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:54:24.603Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bb7d09154209e11a9fdbce8574950e4', 'Board', '9', 'Mathematics', 'math_9_board_algebra', 'Algebra Class 9', 'Remainder factor theorem basic', '[]', '["Quadratic equation","Factorization","Roots"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 2, 0.0, '$$\text{If } x^2 + 5x + 6 = 0, \text{ find the value of } x. $$', '["-2", "-1", "1", "2"]', '-2', 'To find the value of x, we can factorize the quadratic equation.\n\n$$\text{Factorize the quadratic equation: } x^2 + 5x + 6 = (x + 2)(x + 3) = 0$$\n\n$$\text{Solve for } x: x + 2 = 0 \text{ or } x + 3 = 0$$\n\n$$\text{Solve for } x: x = -2 \text{ or } x = -3$$\n\nHowever, we are given that the quadratic equation has only one root.\n\nTherefore, the correct value of x is -2.', '["Factorize the quadratic equation", "Solve for x"]', '', 'general.exam_trap', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:57.054Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bbadb124724ffac6f98f18f0cd1f01c', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Monosaccharides disaccharides polysaccharides', '[]', '["non-reducing sugar","sucrose","glycosidic bond","anomeric carbon","carbohydrate","reducing sugar"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following is a non-reducing sugar?', '["Glucose", "Fructose", "Sucrose", "Maltose"]', 'Sucrose', 'Sucrose lacks free aldehyde or ketone group; cannot reduce Tollens'' or Fehling''s reagent.', '["Step 1: Reducing sugars have free anomeric carbon", "Step 2: Sucrose has glycosidic bond between anomeric carbons", "Step 3: No free group → non-reducing"]', '', 'chemistry.biomolecules.reducing_sugar_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (NEET_EASY->JEE_MAINS_EASY) based on ELO score 1750 and target exam JEEMains', '2026-05-22T15:02:10.584Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bc6f91c756b221618dc2764dc1353e3', 'NEET', '12', 'Biology', 'bio_12_neet_genetics', 'Advanced Genetics for NEET', 'Gene mapping — recombination frequency Morgan units centiMorgan', '[]', '["recombination frequency","genetic distance","gene mapping"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, '$$\text{A gene mapping experiment is performed to study the recombination frequency between two genes. If the recombination frequency is } 20 \text{ centiMorgan, then the distance between the two genes is}$$', '["$\\text{The distance between the two genes is } 20 \\text{ centiMorgan}$", "$\\text{The distance between the two genes is } 2 \\text{ centiMorgan}$", "$\\text{The distance between the two genes is } 0.2 \\text{ centiMorgan}$", "$\\text{The distance between the two genes is } 0.02 \\text{ centiMorgan}$"]', '$\text{The distance between the two genes is } 0.2 \text{ centiMorgan}$', 'Step 1: Recall the definition of recombination frequency and its relation to genetic distance.,Step 2: Use the given recombination frequency to calculate the distance between the two genes.', '["Step 1: Recall the definition of recombination frequency and its relation to genetic distance.", "Step 2: Use the given recombination frequency to calculate the distance between the two genes."]', 'recombination frequency formula', 'bio.genetics.recombination_frequency', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:31.117Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bd228c47f493605399bee686a961ab8', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_integrals', 'Application of Integrals', 'Volume of revolution (disk method)', '[]', '["disk method","volume of solid","definite integral","square root function","π"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, 0.0, 'Find the volume (in $\text{cm}^3$) of the solid obtained by rotating the region bounded by $y=\sqrt{x}$, the $x$‑axis and $x=4$ about the $x$‑axis using the disk method. Give your answer up to two decimal places.', '[]', '25.13', 'The radius of each disk is $y=\sqrt{x}$, so $V=\pi\int_{0}^{4}(\sqrt{x})^{2}dx=\pi\int_{0}^{4}x\,dx=\pi\left[\frac{x^{2}}{2}\right]_{0}^{4}=8\pi\approx25.13$.', '["Step 1: Write the volume integral $V=\\pi\\int_{0}^{4} (\\sqrt{x})^{2}dx$.", "Step 2: Simplify the integrand to $x$.", "Step 3: Evaluate the integral $\\int_{0}^{4} x\\,dx = \\frac{x^{2}}{2}\\big|_{0}^{4}=8$.", "Step 4: Multiply by $\\pi$ to obtain $V = 8\\pi \\approx 25.13$."]', 'V = \pi\int_{a}^{b} [f(x)]^{2}dx', 'mathematics.integrals.disk_method_radius_misuse', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:26:57.434Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bd4ae558a1772a2837fcec4011ae61a', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jadv_improper_integrals', 'Calculus', 'Improper integral convergence', '[]', '["Improper integrals","Comparison test","p‑test","Convergence criteria","Asymptotic behavior"]', 0, 0, '[]', 'MCQ', NULL, 0, 2550, 'JEE_ADV_EASY', 3, -2.0, 'Determine the convergence of the improper integral $$\int_{0}^{\infty} \frac{x^{2}}{x^{4}+1}\,dx.$$', '["Convergent (absolutely)", "Convergent (conditionally)", "Divergent", "Convergent only at the lower limit"]', 'Convergent (absolutely)', 'For large x, the integrand behaves like 1/x^2, whose integral from 1 to ∞ converges. Near 0 the integrand is bounded (≈x^2). Hence the integral converges absolutely.', '["Step 1: Compare the integrand with 1/x^2 for x → ∞.", "Step 2: Use the p‑test (p = 2 > 1) to show convergence at the upper limit.", "Step 3: Observe that the integrand is finite at x = 0, so the lower limit poses no problem."]', 'Comparison test: if f(x) ≤ g(x) and ∫g converges, then ∫f converges', 'math.calculus.improper_integral.convergence', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:14.270Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bd943cb690ab2f8d1cb764c87b788d4', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'Permutations and Combinations', 'Selection with repetition', '[]', '["stars and bars","combinations with repetition","identical objects","distribution problems"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'In how many ways can 5 identical balls be placed into 3 distinct boxes such that a box may contain zero or more balls?', '["18", "21", "24", "27"]', '21', 'This is a classic problem of selection with repetition, equivalent to finding the number of non-negative integer solutions to $x_1 + x_2 + x_3 = 5$. Using the stars and bars method, the number of solutions is $\binom{5 + 3 - 1}{3 - 1} = \binom{7}{2} = 21$.', '["Step 1: Recognize this as a problem of distributing identical items into distinct groups.", "Step 2: Apply the formula for combinations with repetition: $\\binom{n + r - 1}{r - 1}$", "Step 3: Here, $n = 5$ (balls), $r = 3$ (boxes), so $\\binom{5 + 3 - 1}{3 - 1} = \\binom{7}{2}$", "Step 4: Calculate $\\binom{7}{2} = \\frac{7 \\times 6}{2} = 21$."]', '$\binom{n + r - 1}{r - 1}$', 'math.pnc.distribution_forget_formula', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:21.467Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bdf156caf078e1e1620d659f94096a1', 'JEEMains', '11', 'Physics', 'phy_11_shm_velocity', 'Oscillations', 'Simple Harmonic Motion', '[]', '["velocity SHM","angular frequency","amplitude","displacement"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'For a particle executing simple harmonic motion with amplitude $A$ and angular frequency $\omega$, the instantaneous velocity $v$ at displacement $x$ is given by:', '["$v = \\omega\\sqrt{A^{2} - x^{2}}$", "$v = \\omega\\,(A^{2} - x^{2})$", "$v = \\omega\\sqrt{A^{2} + x^{2}}$", "$v = \\omega\\,(A - x)$"]', '$v = \omega\sqrt{A^{2} - x^{2}}$', 'From energy conservation, $\frac{1}{2}kA^{2}=\frac{1}{2}kx^{2}+\frac{1}{2}mv^{2}$ and $k=m\omega^{2}$, giving $v=\omega\sqrt{A^{2}-x^{2}}$. The other forms miss the square‑root or sign.', '["Step 1: Write the total mechanical energy $E=\\frac{1}{2}kA^{2}$.", "Step 2: At displacement $x$, equate $E$ to kinetic plus potential: $\\frac{1}{2}kA^{2}=\\frac{1}{2}kx^{2}+\\frac{1}{2}mv^{2}$.", "Step 3: Substitute $k=m\\omega^{2}$ and solve for $v$.", "Step 4: Simplify to obtain $v=\\omega\\sqrt{A^{2}-x^{2}}$."]', 'v = \omega\sqrt{A^{2} - x^{2}}', 'physics.shm.velocity_expression', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:04:31.521Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7befae3c90e2d10f6f8abb730c429682', 'JEEMains', '11', 'Mathematics', 'math_11_complex_triangle', 'Complex Numbers', 'Triangle inequality', '[]', '["modulus","inequality","complex addition"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'For any two complex numbers $z_1$ and $z_2$, which of the following statements is always true?', '["$|z_1+z_2| = |z_1|+|z_2|$", "$|z_1+z_2| \\le |z_1|+|z_2|$", "$|z_1+z_2| \\ge |z_1|+|z_2|$", "$|z_1+z_2| = \\big|\\,|z_1|-|z_2|\\,\\big|$"]', '$|z_1+z_2| \le |z_1|+|z_2|$', 'The triangle inequality for complex numbers states that the magnitude of the sum does not exceed the sum of the magnitudes: $|z_1+z_2| \le |z_1|+|z_2|$. Equality holds only when $z_1$ and $z_2$ have the same argument.', '["Step 1: Recall the triangle inequality for vectors in the complex plane.", "Step 2: Translate the inequality to modulus notation.", "Step 3: Identify the option that matches the inequality."]', '$|z_1+z_2| \le |z_1|+|z_2|$', 'mathematics.complex.triangle_inequality', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:10.877Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bf280b6682edebbada21535937f4b1e', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Orbital velocity satellite period', '[]', '["orbital velocity","satellite","gravitation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{A satellite is orbiting the Earth at a height of } h = 2R_\oplus \text{ above the surface, where } R_\oplus \text{ is the radius of the Earth.}$$ What is the orbital velocity of the satellite?', '["$\\boxed{\\sqrt{\\frac{GM_\\oplus}{3R_\\oplus}}}$", "$\\sqrt{\\frac{GM_\\oplus}{2R_\\oplus}}$", "$\\sqrt{\\frac{GM_\\oplus}{R_\\oplus}}$", "$\\sqrt{\\frac{GM_\\oplus}{4R_\\oplus}}$"]', '$\boxed{\sqrt{\frac{GM_\oplus}{3R_\oplus}}}$', 'Step 1:  The orbital velocity of a satellite is given by the formula $v = \sqrt{\frac{GM}{r}}$, where $G$ is the gravitational constant, $M$ is the mass of the central body, and $r$ is the radius of the orbit.,Step 2:  We are given that the satellite is orbiting at a height of $h = 2R_\oplus$ above the surface of the Earth, so the radius of the orbit is $r = R_\oplus + h = 3R_\oplus$.,Step 3:  To find the orbital velocity, we need to substitute the values of $G$, $M_\oplus$, and $r$ into the formula and perform the calculation.', '["Step 1: Apply the orbital velocity formula", "Step 2: Substitute the given values into the formula", "Step 3: Perform the calculation to find the orbital velocity"]', 'v = \sqrt{\frac{GM}{r}}', 'general.exam_trap', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:20:32.815Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7bf8ed8c5ee3497fa334ee7df2e4f756', 'JEEMains', '11', 'Physics', 'phy_11_jm_waves', 'Waves', 'Normal modes and harmonics', '[]', '["standing waves","harmonics","wavelength","fixed string"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'A string of length $ L $ is fixed at both ends and vibrates in its third harmonic. What is the wavelength of the standing wave formed?', '["$ \\frac{2L}{3} $", "$ \\frac{L}{3} $", "$ \\frac{3L}{2} $", "$ 3L $"]', '$ \frac{2L}{3} $', 'For a string fixed at both ends, the wavelength in the $ n $-th harmonic is given by $ \lambda_n = \frac{2L}{n} $. For the third harmonic ($ n = 3 $), $ \lambda = \frac{2L}{3} $. The other options arise from incorrect application of formula (e.g., using $ L/n $ or $ nL $).', '["Step 1: Recall formula for wavelength in normal modes: $ \\lambda_n = \\frac{2L}{n} $.", "Step 2: Identify $ n = 3 $ for third harmonic.", "Step 3: Substitute into formula: $ \\lambda = \\frac{2L}{3} $.", "Step 4: Reject options with $ L/3 $, $ 3L $, or $ 3L/2 $ as incorrect derivations."]', '\lambda_n = \frac{2L}{n}', 'physics.waves.harmonic_formula_misuse', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:57:02.161Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c05c685b9e57f93cd24d7e24b47410f', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Divisibility and Euclidean algorithm', '[]', '["divisibility","Euclidean algorithm","gcd","lcm","product relation","modular arithmetic","prime factorization"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Let $a$ and $b$ be positive integers such that $\gcd(a,b)=12$ and $\operatorname{lcm}(a,b)=180$. Which of the following statements are necessarily true?', '["$a$ and $b$ are both multiples of 12.", "$a$ divides 180.", "$a+b$ is divisible by 24.", "The product $ab$ equals $12 \\times 180$."]', '["$A$ AND $B$ ARE BOTH MULTIPLES OF 12.", "$A$ DIVIDES 180.", "$A+B$ IS DIVISIBLE BY 24.", "THE PRODUCT $AB$ EQUALS $12 \tIMES 180$."]', 'Write $a=12x$, $b=12y$ with $\gcd(x,y)=1$. From $\operatorname{lcm}=12xy=180$ we get $xy=15$, so $x$ and $y$ are odd. Hence $a$ and $b$ are multiples of 12 (A), each divides 180 (B), and $a+b=12(x+y)$ is a multiple of 24 because $x+y$ is even (C). Moreover $ab=\gcd\times\operatorname{lcm}=12\times180$ (D).', '["Step 1: Express $a$ and $b$ as $a=12x$, $b=12y$ with $\\gcd(x,y)=1$.", "Step 2: Use the lcm relation $12xy=180$ to obtain $xy=15$.", "Step 3: Observe that $x$ and $y$ must both be odd, making $x+y$ even.", "Step 4: Derive each statement from these facts and verify their truth."]', 'a\,b = \gcd(a,b)\,\operatorname{lcm}(a,b)', 'math.number_theory.gcd_lcm_relation', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:57.778Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c088142a225aaa24c997b525d911c4e', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_equilibrium', 'Equilibrium', 'Buffer solutions', '[]', '["buffer_solution","henderson_hasselbalch","ph_calculation"]', 0, 0, '["NEET"]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, 0.0, 'Calculate pH of buffer with $pK_a=4.74$, $[salt]=0.1$ M, $[acid]=0.1$ M.', '[]', '4.74', 'Using Henderson-Hasselbalch: $pH = pK_a + \log(1) = pK_a$.', '["Step 1: Use $pH = pK_a + \\log([salt]/[acid])$.", "Step 2: Since ratio is 1, $\\log(1)=0$, so $pH = 4.74$."]', 'pH = pK_a + \log([salt]/[acid])', 'chemistry.equilibrium.log_ratio_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:45:47.492Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c08e22ff2f220b610c175912f3447f5', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_surface_colloids', 'Surface Chemistry', 'Colloidal preparation methods', '[]', '["colloidal stability","chemical reduction","Brownian motion","Tyndall effect","nanoparticle size"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Which of the following methods is most suitable for preparing a stable colloidal solution of silver sulfide (Ag₂S) with particle size in the range of 10–20 nm?', '["Reduction of AgNO₃ with NaBH₄ in aqueous medium (chemical reduction method)", "Precipitation by adding excess NaCl to AgNO₃ solution (common ion method)", "Digestive (gel) method using hot alkaline solution", "Lyophilisation of a saturated Ag₂S solution"]', 'Reduction of AgNO₃ with NaBH₄ in aqueous medium (chemical reduction method)', 'The chemical reduction method using NaBH₄ rapidly reduces Ag⁺ to Ag⁰, forming Ag₂S nuclei that grow to nanometre size while Brownian motion stabilises them. Other methods either give large precipitates or are unsuitable for Ag₂S.', '["Step 1: Identify a method that provides rapid nucleation and prevents agglomeration.", "Step 2: Recognise that NaBH₄ is a strong reducing agent that creates nanometre‑sized Ag nuclei.", "Step 3: The reduced Ag reacts with S²⁻ to form Ag₂S colloids; stabilisation occurs via the Tyndall effect.", "Step 4: Conclude that the chemical reduction route yields the desired stable colloid."]', 'D = \frac{k_{B} T}{6\pi \eta r}', 'chemistry.colloids.preparation_method', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:12.838Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c095b262d544db20a4e685ccb461397', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_coordination', 'Coordination Compounds', 'Spectrochemical series', '[]', '["spectrochemical series","ligand field theory","crystal field splitting","strong field ligand","octahedral complex"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'In the spectrochemical series, which of the following ligands is a strong‑field ligand that will produce a large crystal‑field splitting energy (Δ) in an octahedral complex of a first‑row transition metal?', '["NH₃", "H₂O", "Cl⁻", "F⁻"]', 'NH₃', 'The spectrochemical series orders ligands by field strength: I⁻ < Br⁻ < S²⁻ < SCN⁻ < Cl⁻ < N₃⁻ < F⁻ < OH⁻ < C₂O₄²⁻ < H₂O < NH₃ < en < NO₂⁻ < CN⁻. NH₃ appears near the strong‑field end, giving a large Δ.', '["Step 1: Recall the order of ligands in the spectrochemical series.", "Step 2: Identify ligands that lie on the strong‑field side.", "Step 3: Choose NH₃, which is classified as a strong‑field ligand."]', '', 'chemistry.coord.spectrochemical_series', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:43.559Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c0da0623a3f31c2be6044b92430b07c', 'JEEAdvanced', '12', 'Mathematics', 'math_12_je_adv_func_eq_rational', 'Functional Equations', 'Functions on rationals vs reals', '[]', '["functional equation","additive property","rational numbers","linearity","extension"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 3, -2.0, 'Let $f:\mathbb{Q}\to\mathbb{R}$ satisfy $f(x+1)=f(x)+2$ for all rational $x$, and $f(0)=0$. Which of the following statements are necessarily true?', '["$f(x)=2x$ for all rational $x$", "$f$ is linear on $\\mathbb{Q}$", "$f$ can be extended to a continuous function on $\\mathbb{R}$", "$f$ is bounded on the interval $[0,1]$"]', '["[\"$F(X)=2X$ FOR ALL RATIONAL $X$\",\"$F$ IS LINEAR ON $\\MATHBB{Q}$\",\"$F$ IS BOUNDED ON THE INTERVAL $[0,1]$\"]"]', 'Using the given functional equation repeatedly shows $f(n)=2n$ for all integers $n$, and for a rational $p/q$, $f(p/q)=2p/q$. Hence $f(x)=2x$ on $\mathbb{Q}$, making it linear and bounded on $[0,1]$. Continuity on $\mathbb{R}$ is not guaranteed by the condition alone.', '["Step 1: Apply the relation to integers to obtain $f(n)=2n$.", "Step 2: For a rational $p/q$, write $p/q = (1/q)+(1/q)+\\dots$ $p$ times and use the relation to get $f(p/q)=2p/q$.", "Step 3: Conclude that $f$ is $2x$ on $\\mathbb{Q}$, which implies linearity and boundedness on $[0,1]$."]', '$f(x+1)=f(x)+2$', 'math.functional_equations.rational_extension', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:39.196Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c141d6543f1b9654cad1ccc74b6d891', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_haloalkanes', 'Haloalkanes and Haloarenes', 'SN1 vs SN2 mechanisms', '[]', '["SN1 mechanism","carbocation stability","tert‑butyl bromide","nucleophilic substitution","reaction pathway"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'When 2‑bromo‑2‑methylpropane reacts with aqueous NaOH, the major product is tert‑butanol. Which of the following statements correctly explains the observed reaction pathway?', '["The reaction proceeds via an SN2 mechanism because the substrate is primary.", "The reaction proceeds via an SN1 mechanism because the substrate forms a stable tertiary carbocation.", "The reaction proceeds via an E2 mechanism due to the strong base.", "The reaction proceeds via a concerted SN1/SN2 mechanism because of steric hindrance."]', 'The reaction proceeds via an SN1 mechanism because the substrate forms a stable tertiary carbocation.', '2‑bromo‑2‑methylpropane is a tertiary alkyl halide; such substrates favor the SN1 pathway, forming a stable tertiary carbocation that is then attacked by OH⁻ to give tert‑butanol.', '["Step 1: Identify the substrate as a tertiary alkyl halide.", "Step 2: Recognize that tertiary substrates stabilize carbocations, favoring SN1.", "Step 3: Conclude that nucleophilic attack on the carbocation yields tert‑butanol."]', '', 'chemistry.organic.sn1_vs_sn2', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:45.347Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c17db8ff0d428f9f4abd7d515f14362', 'NEET', '11', 'Biology', 'bio_11_neet_cellular_respiration', 'Biology', 'Cellular Respiration', '[]', '["Krebs cycle","NADH","FADH2","intermediate metabolites","energy carriers"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'During the Krebs cycle, which of the following pairs of intermediates directly generate the reduced coenzymes NADH and FADH₂?', '["α‑Ketoglutarate and Succinyl‑CoA", "Citrate and Isocitrate", "Malate and Oxaloacetate", "Succinate and Fumarate"]', 'α‑Ketoglutarate and Succinyl‑CoA', 'α‑Ketoglutarate dehydrogenase converts α‑ketoglutarate to Succinyl‑CoA, producing one NADH. The conversion of Succinate to Fumarate by succinate‑dehydrogenase yields one FADH₂. These steps are the only ones that directly generate NADH and FADH₂ in the cycle.', '["Step 1: List the reactions of the Krebs cycle that involve redox changes.", "Step 2: Identify the step where α‑ketoglutarate is converted to Succinyl‑CoA (produces NADH).", "Step 3: Identify the step where Succinate is oxidized to Fumarate (produces FADH₂).", "Step 4: Choose the option containing both intermediates."]', '', 'biology.respiration.krebs_intermediate', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:34:57.822Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('7c1dc16666ef01b4db34b7b7ff0a261e', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_1d', 'Motion in a Straight Line', 'Velocity-time graphs', '[]', '["vt_graph","displacement","area_under_curve","kinematics"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, 0.0, 'Velocity $v=4t$ m/s. Displacement from $t=0$ to $t=2$ s is?', '[]', '8', 'Area under v-t graph = $\frac{1}{2} \times 2 \times 8 = 8$ m.', '["Calculate area under v-t graph", "Use triangle area formula", "Compute displacement"]', 'Displacement = Area under v-t graph', 'physics.kinematics.graph_interpretation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:56.924Z', 1);
